(44316, 637, 244, '<td valign="top">good concept, nice color, love the reflections</td>', 'good concept, nice color, love the reflections', '2002-04-08 22:49:00.000000', NULL, 1),
(44317, 637, 446, '<td valign="top">Great concept.  The blown highlights work well for this shot.  Gives it a real "high tech" feeling.  Just goes to prove that following all of the "rules" is not always the right thing.</td>', 'Great concept.  The blown highlights work well for this shot.  Gives it a real "high tech" feeling.  Just goes to prove that following all of the "rules" is not always the right thing.', '2002-04-09 00:02:00.000000', NULL, 1),
