(44319, 637, 797, '<td valign="top">the colors are gripping. thanks for this one.</td>', 'the colors are gripping. thanks for this one.', '2002-04-09 08:42:00.000000', NULL, 1),
(44320, 637, 312, '<td valign="top">i like this shot. it''s crisp and the colors are great.</td>', 'i like this shot. it''s crisp and the colors are great.', '2002-04-09 09:31:00.000000', NULL, 1),
