(44634, 657, 279, '<td valign="top">Nice use of the vertical frame.</td>', 'Nice use of the vertical frame.', '2002-04-08 17:11:00.000000', NULL, 1),
(44635, 657, 244, '<td valign="top">I think this shot would have been alot better in B+W, the colors in the window are a little distracting, also a different time of day might have been better, looks like around noon, late afternoon or early morning would have reduced the harshness of the light.</td>', 'I think this shot would have been alot better in B+W, the colors in the window are a little distracting, also a different time of day might have been better, looks like around noon, late afternoon or early morning would have reduced the harshness of the light.', '2002-04-08 21:38:00.000000', NULL, 1),
(44636, 657, 749, '<td valign="top">Nice repetition, but the eye is drawn more to the copper-colour behind, rather than the ironwork.</td>', 'Nice repetition, but the eye is drawn more to the copper-colour behind, rather than the ironwork.', '2002-04-09 03:35:00.000000', NULL, 1),
(44637, 657, 472, '<td valign="top">youve done a good job iwth the exposure and focus. i would go in closer tho on the rails themselves.</td>', 'youve done a good job iwth the exposure and focus. i would go in closer tho on the rails themselves.', '2002-04-09 12:12:00.000000', NULL, 1),
(44638, 657, 139, '<td valign="top">Nice idea.  I like the picture, but the colors are distracting, and that can''t really be helped :(</td>', 'Nice idea.  I like the picture, but the colors are distracting, and that can''t really be helped :(', '2002-04-09 12:37:00.000000', NULL, 1),
(44639, 657, 883, '<td valign="top">Nice and crisp shot, fine technically.  Not my choice of subject though.  To me it doesn''t instantly pop out and say anything.  I don''t feel any emotion with it.</td>', 'Nice and crisp shot, fine technically.  Not my choice of subject though.  To me it doesn''t instantly pop out and say anything.  I don''t feel any emotion with it.', '2002-04-09 13:22:00.000000', NULL, 1),
(44640, 657, 884, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2002-04-09 14:13:00.000000', NULL, 1),
(44641, 657, 714, '<td valign="top">Is that a window and is someone peaking out?  It took me awhile to figure out what it was.  Great picture.  :)</td>', 'Is that a window and is someone peaking out?  It took me awhile to figure out what it was.  Great picture.  :)', '2002-04-09 16:37:00.000000', NULL, 1),
