(44655, 658, 472, '<td valign="top">subject is strange ..</td>', 'subject is strange ..', '2002-04-08 21:04:00.000000', NULL, 1),
(44656, 658, 749, '<td valign="top">The lack of direct lighting onto the heads of the flowers really helps emphasise the dead / dying aspect, but I would prefer a little more focus on the petals.</td>', 'The lack of direct lighting onto the heads of the flowers really helps emphasise the dead / dying aspect, but I would prefer a little more focus on the petals.', '2002-04-09 03:46:00.000000', NULL, 1),
(44657, 658, 139, '<td valign="top">The curves on the vase are very interesting.  A more interesting image to me would have been without the roses.</td>', 'The curves on the vase are very interesting.  A more interesting image to me would have been without the roses.', '2002-04-09 04:03:00.000000', NULL, 1),
(44658, 658, 441, '<td valign="top">Main subject for focus should be the flowers but this would detract from ''curves'' challenge, you have a dilemma hear but original idea.  Don''t be offended, keep trying!</td>', 'Main subject for focus should be the flowers but this would detract from ''curves'' challenge, you have a dilemma hear but original idea.  Don''t be offended, keep trying!', '2002-04-09 13:42:00.000000', NULL, 1),
