(44663, 658, 955, '<td valign="top">dead flowers look sad and out of focus - not sure what you are trying to do.</td>', 'dead flowers look sad and out of focus - not sure what you are trying to do.', '2002-04-10 18:15:00.000000', NULL, 1),
(44664, 658, 142, '<td valign="top">Very artistic.</td>', 'Very artistic.', '2002-04-11 11:40:00.000000', NULL, 1),
