(44693, 660, 441, '<td valign="top">nice curves but can''t help looking into dark areas for more detail - presumably you did not want to show detail there?</td>', 'nice curves but can''t help looking into dark areas for more detail - presumably you did not want to show detail there?', '2002-04-10 14:51:00.000000', NULL, 1),
