(44707, 662, 641, '<td valign="top">Nice color tones and lighting.</td>', 'Nice color tones and lighting.', '2002-04-09 08:56:00.000000', NULL, 1),
(44708, 662, 352, '<td valign="top">Simple, nice!!  I like this one!</td>', 'Simple, nice!!  I like this one!', '2002-04-09 11:01:00.000000', NULL, 1),
