(44874, 680, 509, '<td valign="top">I''m not wild about fake flowers, but the colors and focus are good</td>', 'I''m not wild about fake flowers, but the colors and focus are good', '2002-04-08 11:40:00.000000', NULL, 1),
(44875, 680, 772, '<td valign="top">I love pastel colors in your photograph.  I think my problem is that I have seen too many flower photograohs this spring.  Are these flowers under glass?  The reflections on the lower right and upper left are minutely distracting from the subject.....</td>', 'I love pastel colors in your photograph.  I think my problem is that I have seen too many flower photograohs this spring.  Are these flowers under glass?  The reflections on the lower right and upper left are minutely distracting from the subject.....', '2002-04-08 12:35:00.000000', NULL, 1),
(44876, 680, 813, '<td valign="top">way symmetrical and dead-on centered composition yet it works. maybe it''s the color. very nice.</td>', 'way symmetrical and dead-on centered composition yet it works. maybe it''s the color. very nice.', '2002-04-08 13:35:00.000000', NULL, 1),
(44877, 680, 749, '<td valign="top">Good symmetry, and great colours, but a touch more detail on the petals would set off the blurring effect of the glass.</td>', 'Good symmetry, and great colours, but a touch more detail on the petals would set off the blurring effect of the glass.', '2002-04-08 16:21:00.000000', NULL, 1),
(44878, 680, 714, '<td valign="top">There are a lot of reflections off the glass in this photo and the light on the bottom right hand corner is distracting.  I love the idea of the flowers.  :)</td>', 'There are a lot of reflections off the glass in this photo and the light on the bottom right hand corner is distracting.  I love the idea of the flowers.  :)', '2002-04-08 17:21:00.000000', NULL, 1),
(44879, 680, 279, '<td valign="top">Shouldn''t have had it so centered, it''s a little too... Simple, I guess.</td>', 'Shouldn''t have had it so centered, it''s a little too... Simple, I guess.', '2002-04-08 17:27:00.000000', NULL, 1),
(44880, 680, 441, '<td valign="top">Beatiful pastel colours and vibrant at the same time!</td>', 'Beatiful pastel colours and vibrant at the same time!', '2002-04-08 18:40:00.000000', NULL, 1),
(44881, 680, 472, '<td valign="top">wow!  unreal.  amazing that this was not using photoshop! colors, exposure, DOF, all perfect.</td>', 'wow!  unreal.  amazing that this was not using photoshop! colors, exposure, DOF, all perfect.', '2002-04-08 21:00:00.000000', NULL, 1),
(44882, 680, 244, '<td valign="top">Great colors, the reflection in the glass is a little distracting did you shoot it through glass?</td>', 'Great colors, the reflection in the glass is a little distracting did you shoot it through glass?', '2002-04-08 21:47:00.000000', NULL, 1),
(44883, 680, 57, '<td valign="top">Beautiful!  I thought about entering a rose, too, but your photo is much nicer than the one I had.</td>', 'Beautiful!  I thought about entering a rose, too, but your photo is much nicer than the one I had.', '2002-04-08 22:14:00.000000', NULL, 1),
(44884, 680, 428, '<td valign="top">I love the flowers! I would have liked to have seen the pink one on the bottom too! Or if the subject was the one in the center, it should have been a tighter shot.</td>', 'I love the flowers! I would have liked to have seen the pink one on the bottom too! Or if the subject was the one in the center, it should have been a tighter shot.', '2002-04-09 13:42:00.000000', NULL, 1),
(44885, 680, 549, '<td valign="top">nice and curvy. Seems a bit on the washed out side as far as contrast goes.</td>', 'nice and curvy. Seems a bit on the washed out side as far as contrast goes.', '2002-04-09 21:38:00.000000', NULL, 1),
(44886, 680, 929, '<td valign="top">Very beautiful photo.</td>', 'Very beautiful photo.', '2002-04-10 09:24:00.000000', NULL, 1),
