(45034, 697, 428, '<td valign="top">nice shot!  I love the sun beams!  good focus and composition</td>', 'nice shot!  I love the sun beams!  good focus and composition', '2002-04-08 21:47:00.000000', NULL, 1),
(45035, 697, 57, '<td valign="top">The light reflecting off the curved sides is awesome.  I don''t care for the shape of the whole thing, though, so it might have been nice to crop in closer, to focus on the reflective edge.</td>', 'The light reflecting off the curved sides is awesome.  I don''t care for the shape of the whole thing, though, so it might have been nice to crop in closer, to focus on the reflective edge.', '2002-04-08 21:48:00.000000', NULL, 1),
(45036, 697, 689, '<td valign="top">Nice effect with the sun ...</td>', 'Nice effect with the sun ...', '2002-04-08 22:41:00.000000', NULL, 1),
(45037, 697, 587, '<td valign="top">This is great, especially like the ray of light captured coming down on it!</td>', 'This is great, especially like the ray of light captured coming down on it!', '2002-04-09 06:58:00.000000', NULL, 1),
(45038, 697, 352, '<td valign="top">Good time of day and angle choice.  I like how the rays at the top enter the shot and illuminate your subject.  The front is a bit dull, I wonder what the use of a reflctor would have done to the loghting of it?  Still a good shot!</td>', 'Good time of day and angle choice.  I like how the rays at the top enter the shot and illuminate your subject.  The front is a bit dull, I wonder what the use of a reflctor would have done to the loghting of it?  Still a good shot!', '2002-04-09 10:14:00.000000', NULL, 1),
(45039, 697, 326, '<td valign="top">This is way to cool! Great find and nice shot!</td>', 'This is way to cool! Great find and nice shot!', '2002-04-09 11:14:00.000000', NULL, 1),
(45040, 697, 813, '<td valign="top">Nice sculpture. Photograph would be stronger by cropping tightly on the curves.</td>', 'Nice sculpture. Photograph would be stronger by cropping tightly on the curves.', '2002-04-09 11:14:00.000000', NULL, 1),
(45041, 697, 117, '<td valign="top">I like the way you mixed the light and shadows</td>', 'I like the way you mixed the light and shadows', '2002-04-09 14:02:00.000000', NULL, 1),
(45042, 697, 886, '<td valign="top">Architect''s work: interesting. Photographer''s: so-so.</td>', 'Architect''s work: interesting. Photographer''s: so-so.', '2002-04-09 15:36:00.000000', NULL, 1),
(45043, 697, 280, '<td valign="top">i like the rays of light in the top left hand corner.</td>', 'i like the rays of light in the top left hand corner.', '2002-04-09 16:30:00.000000', NULL, 1),
(45044, 697, 139, '<td valign="top">It may have been better if the sun was hitting the side you were taking the picture of.</td>', 'It may have been better if the sun was hitting the side you were taking the picture of.', '2002-04-09 17:12:00.000000', NULL, 1),
(45045, 697, 714, '<td valign="top">The object looks like it is giving off some sort of energy the way the sun is shining on it. I would have liked it even more if the bottom was cropped.  What do you think.  Nice pic.  :)</td>', 'The object looks like it is giving off some sort of energy the way the sun is shining on it. I would have liked it even more if the bottom was cropped.  What do you think.  Nice pic.  :)', '2002-04-10 10:43:00.000000', NULL, 1),
(45046, 697, 245, '<td valign="top">the sun shining is is a nice touch, but the ground and hilights on the statue are blown out. I would have framed it slightly to the left, about 5%, or tried to fiund an angle where the planter in the background wasn''t so visible.</td>', 'the sun shining is is a nice touch, but the ground and hilights on the statue are blown out. I would have framed it slightly to the left, about 5%, or tried to fiund an angle where the planter in the background wasn''t so visible.', '2002-04-10 12:50:00.000000', NULL, 1),
(45047, 697, 347, '<td valign="top">Nice sunbeam... it''s a pretty staid angle for such a potentially interesting object, though.</td>', 'Nice sunbeam... it''s a pretty staid angle for such a potentially interesting object, though.', '2002-04-10 15:20:00.000000', NULL, 1),
(45048, 697, 441, '<td valign="top">Cracking subject, superb lighting - the shafts of light are terrific!</td>', 'Cracking subject, superb lighting - the shafts of light are terrific!', '2002-04-10 15:42:00.000000', NULL, 1),
(45049, 697, 131, '<td valign="top">That''s good. needs an object next to it other than a person to show the size of this sculpture</td>', 'That''s good. needs an object next to it other than a person to show the size of this sculpture', '2002-04-10 19:22:00.000000', NULL, 1),
(45050, 697, 2, '<td valign="top">A non-creative picture of someone else''s art is not appealing.</td>', 'A non-creative picture of someone else''s art is not appealing.', '2002-04-11 10:09:00.000000', NULL, 1),
(45051, 697, 301, '<td valign="top">I love those sun rays ... how did u get that?</td>', 'I love those sun rays ... how did u get that?', '2002-04-11 12:10:00.000000', NULL, 1),
(45052, 697, 705, '<td valign="top">nice framing; nice light; I suspect that the piece is a grander than this photo makes it out to be-maybe a lower perspective would help</td>', 'nice framing; nice light; I suspect that the piece is a grander than this photo makes it out to be-maybe a lower perspective would help', '2002-04-13 02:32:00.000000', NULL, 1),
(45053, 697, 739, '<td valign="top">Nice flare on the corner</td>', 'Nice flare on the corner', '2002-04-13 10:23:00.000000', NULL, 1),
(45054, 697, 1, '<td valign="top">Whether on purpose or not, the light adds a nice touch to it.</td>', 'Whether on purpose or not, the light adds a nice touch to it.', '2002-04-13 10:36:00.000000', NULL, 1),
(45055, 697, 554, '<td valign="top">the ray of light really makes this one great.</td>', 'the ray of light really makes this one great.', '2002-04-14 16:48:00.000000', NULL, 1),
(45056, 697, 955, '<td valign="top">Excellent choice, shaft of light adds to impact. Good control of light.  Would prefer base and seat in lower right to be cropped from picture.</td>', 'Excellent choice, shaft of light adds to impact. Good control of light.  Would prefer base and seat in lower right to be cropped from picture.', '2002-04-14 21:50:00.000000', NULL, 1),
(45065, 700, 656, '<td valign="top">Good shot.  Bit out of focus ?</td>', 'Good shot.  Bit out of focus ?', '2002-04-08 10:37:00.000000', NULL, 1),
(45066, 700, 718, '<td valign="top">Interestin.  I had the same idea but I didn''t go with it.</td>', 'Interestin.  I had the same idea but I didn''t go with it.', '2002-04-08 12:26:00.000000', NULL, 1),
(45067, 700, 772, '<td valign="top">You have done a good job with the focus on this photograph.  Some similar ones I have seen haven''t managed to get the focus on the subject of the image...</td>', 'You have done a good job with the focus on this photograph.  Some similar ones I have seen haven''t managed to get the focus on the subject of the image...', '2002-04-08 12:31:00.000000', NULL, 1),
(45068, 700, 834, '<td valign="top">very original<br/></td>', 'very original', '2002-04-08 13:07:00.000000', NULL, 1),
(45069, 700, 280, '<td valign="top">Nice contrast between the wire and the soft clouds. Although technically I think thats razor wire not barbed   : )</td>', 'Nice contrast between the wire and the soft clouds. Although technically I think thats razor wire not barbed   : )', '2002-04-08 14:21:00.000000', NULL, 1),
(45070, 700, 509, '<td valign="top">The sky is a little dark, I''m guessing it was pretty bright out when you took this.  I would have lightened it a bit in post production.  Also, there is a hint of compression around the wire itself.  Other than that, though, this is a very cool photo.</td>', 'The sky is a little dark, I''m guessing it was pretty bright out when you took this.  I would have lightened it a bit in post production.  Also, there is a hint of compression around the wire itself.  Other than that, though, this is a very cool photo.', '2002-04-08 15:45:00.000000', NULL, 1),
(45071, 700, 92, '<td valign="top">I really like this. I do wish the blue had a bit more deepth to it.</td>', 'I really like this. I do wish the blue had a bit more deepth to it.', '2002-04-08 18:20:00.000000', NULL, 1),
(45072, 700, 587, '<td valign="top">I like the contrast of harsh metal against soft clouds with baby blue sky - just wish it was focused more.</td>', 'I like the contrast of harsh metal against soft clouds with baby blue sky - just wish it was focused more.', '2002-04-09 06:20:00.000000', NULL, 1),
(45073, 700, 352, '<td valign="top">The gracefulness of the curves competes with the harsh hanture of the object that creates them.  Excellent!!</td>', 'The gracefulness of the curves competes with the harsh hanture of the object that creates them.  Excellent!!', '2002-04-09 11:02:00.000000', NULL, 1),
(45074, 700, 472, '<td valign="top">luckily its'' a sunny day or this would feel like a concentration camp!</td>', 'luckily its'' a sunny day or this would feel like a concentration camp!', '2002-04-09 12:16:00.000000', NULL, 1),
(45075, 700, 441, '<td valign="top">Striking image.</td>', 'Striking image.', '2002-04-09 12:59:00.000000', NULL, 1),
(45076, 700, 549, '<td valign="top">nice and artsy. See the other barbedwire shot for an improvement on this idea.</td>', 'nice and artsy. See the other barbedwire shot for an improvement on this idea.', '2002-04-09 21:50:00.000000', NULL, 1),
(45077, 700, 926, '<td valign="top">I like the division of the sky by the razor wire.  If there were more background detail, it might be better</td>', 'I like the division of the sky by the razor wire.  If there were more background detail, it might be better', '2002-04-10 09:22:00.000000', NULL, 1),
(45078, 700, 245, '<td valign="top">The picture''s underexposed, making the clouds look dark, and I''m not really drawn to a focal point to hold my interest. Try adjusting the levels to brighten it!</td>', 'The picture''s underexposed, making the clouds look dark, and I''m not really drawn to a focal point to hold my interest. Try adjusting the levels to brighten it!', '2002-04-10 13:12:00.000000', NULL, 1),
(45079, 700, 347, '<td valign="top">What is it with watches and razor wire in this one? Nice pic, tho.</td>', 'What is it with watches and razor wire in this one? Nice pic, tho.', '2002-04-10 15:24:00.000000', NULL, 1),
(45080, 700, 428, '<td valign="top">original idea, you may need a little more light on your subject</td>', 'original idea, you may need a little more light on your subject', '2002-04-10 21:51:00.000000', NULL, 1),
(45081, 700, 139, '<td valign="top">Good eye.  I love these curves, and the background is great also.</td>', 'Good eye.  I love these curves, and the background is great also.', '2002-04-11 01:59:00.000000', NULL, 1),
(45082, 700, 714, '<td valign="top">Ouch!  Great way to capture curves.   Simple and nice. :)</td>', 'Ouch!  Great way to capture curves.   Simple and nice. :)', '2002-04-11 10:19:00.000000', NULL, 1),
(45083, 700, 113, '<td valign="top">I also thought of doing barbed wire.  I like the design but more clarity would have been nice</td>', 'I also thought of doing barbed wire.  I like the design but more clarity would have been nice', '2002-04-11 16:03:00.000000', NULL, 1),
(45084, 700, 554, '<td valign="top">very unusual wire   nice framing</td>', 'very unusual wire   nice framing', '2002-04-14 19:46:00.000000', NULL, 1),
(45085, 700, 955, '<td valign="top">good composition and light control</td>', 'good composition and light control', '2002-04-14 21:22:00.000000', NULL, 1),
(45086, 704, 656, '<td valign="top">Good abstract shot.  Cropped a bit too tightly on the right hand side which spoils the symmetry.</td>', 'Good abstract shot.  Cropped a bit too tightly on the right hand side which spoils the symmetry.', '2002-04-08 10:26:00.000000', NULL, 1),
(45087, 704, 772, '<td valign="top">This photo made my top 20... On closer inspection, I am noticing that the left side of the speaker cavity is out of focus.  I know how difficult it is to achieve depth of field on a macro shot.  I like the composition of this photo and keep up the good work!  Score: 7</td>', 'This photo made my top 20... On closer inspection, I am noticing that the left side of the speaker cavity is out of focus.  I know how difficult it is to achieve depth of field on a macro shot.  I like the composition of this photo and keep up the good work!  Score: 7', '2002-04-08 15:03:00.000000', NULL, 1),
(45088, 704, 811, '<td valign="top">Sharp.  Caught my attention quickly.  The more I look at it the more I like it.</td>', 'Sharp.  Caught my attention quickly.  The more I look at it the more I like it.', '2002-04-08 15:46:00.000000', NULL, 1),
(45089, 704, 749, '<td valign="top">The light reflecting through helps emphasise the curves, but I can''t help feeling that if it was slightly more symmetrical it would be even better.</td>', 'The light reflecting through helps emphasise the curves, but I can''t help feeling that if it was slightly more symmetrical it would be even better.', '2002-04-08 15:59:00.000000', NULL, 1),
(45090, 704, 428, '<td valign="top">nice photo, looks a bit out of focus, and I think I would have tried to move the camera to the right just a bit. good capture of the theme</td>', 'nice photo, looks a bit out of focus, and I think I would have tried to move the camera to the right just a bit. good capture of the theme', '2002-04-08 21:41:00.000000', NULL, 1),
(45091, 704, 57, '<td valign="top">Very nice.  Like the lighting and textures.</td>', 'Very nice.  Like the lighting and textures.', '2002-04-08 22:27:00.000000', NULL, 1),
(45092, 704, 446, '<td valign="top">Nice crisp image.  I gave it a 9.  Would have voted a 10 except to my eye a slightly wider aperture should have been used to get the left edge of the speaker housing in focus.  I understand you may have had a different intent.  I like your style.</td>', 'Nice crisp image.  I gave it a 9.  Would have voted a 10 except to my eye a slightly wider aperture should have been used to get the left edge of the speaker housing in focus.  I understand you may have had a different intent.  I like your style.', '2002-04-08 23:56:00.000000', NULL, 1),
(45093, 704, 587, '<td valign="top">cool shot!</td>', 'cool shot!', '2002-04-09 06:44:00.000000', NULL, 1),
(45094, 704, 641, '<td valign="top">Wow, now that''s a speaker.</td>', 'Wow, now that''s a speaker.', '2002-04-09 08:27:00.000000', NULL, 1),
(45095, 704, 797, '<td valign="top">lots of musical themes this time eh?  you must have a sharp eye for little things.  i would never have thought of looking into my speaker for inspiration!  high marks from me.</td>', 'lots of musical themes this time eh?  you must have a sharp eye for little things.  i would never have thought of looking into my speaker for inspiration!  high marks from me.', '2002-04-09 08:42:00.000000', NULL, 1),
(45096, 704, 863, '<td valign="top">Interesting subject!</td>', 'Interesting subject!', '2002-04-09 10:03:00.000000', NULL, 1),
(45097, 704, 352, '<td valign="top">Interesting angle</td>', 'Interesting angle', '2002-04-09 11:10:00.000000', NULL, 1),
(45098, 704, 472, '<td valign="top">niice abstract.  great techno futuristic feel!</td>', 'niice abstract.  great techno futuristic feel!', '2002-04-09 12:13:00.000000', NULL, 1),
(45099, 704, 720, '<td valign="top">Awesome idea. Looks like an entry to some parallel universe, haha. You get a ten from me!</td>', 'Awesome idea. Looks like an entry to some parallel universe, haha. You get a ten from me!', '2002-04-09 12:29:00.000000', NULL, 1),
(45100, 704, 734, '<td valign="top">Nice macro, I would like to see this image at another angle, i think it might be more dramatic</td>', 'Nice macro, I would like to see this image at another angle, i think it might be more dramatic', '2002-04-09 12:34:00.000000', NULL, 1),
(45101, 704, 280, '<td valign="top">I like this shot but it may have been more effective in B&amp;W.</td>', 'I like this shot but it may have been more effective in B&W.', '2002-04-09 14:00:00.000000', NULL, 1),
(45102, 704, 714, '<td valign="top">I would never have thought of that!  Good picture.  :)</td>', 'I would never have thought of that!  Good picture.  :)', '2002-04-09 16:10:00.000000', NULL, 1),
(45103, 704, 139, '<td valign="top">Interesting.  I would have liked it better if you had gotten in closer to where you can''t see the speaker grid at the top or bottom.   It would have been much more abstract, and I think I would be able to better focus on the curves.</td>', 'Interesting.  I would have liked it better if you had gotten in closer to where you can''t see the speaker grid at the top or bottom.   It would have been much more abstract, and I think I would be able to better focus on the curves.', '2002-04-09 17:13:00.000000', NULL, 1),
(45104, 704, 884, '<td valign="top">Awesome-looking; a ten for you!</td>', 'Awesome-looking; a ten for you!', '2002-04-09 20:27:00.000000', NULL, 1),
(45105, 704, 549, '<td valign="top">nice curvy cave or futuristic entrance. Nice job and nice lighting.</td>', 'nice curvy cave or futuristic entrance. Nice job and nice lighting.', '2002-04-09 21:44:00.000000', NULL, 1),
(45106, 704, 441, '<td valign="top">superb detail and subject.</td>', 'superb detail and subject.', '2002-04-10 14:31:00.000000', NULL, 1),
(45107, 704, 347, '<td valign="top">This is kind of cute, but it''s interesting that it looks better in thumbnail than full size -- perhaps due to depth of field constraints or unavoidable jaggies on the boundary between the silver and black. Overall a nice shot, though.</td>', 'This is kind of cute, but it''s interesting that it looks better in thumbnail than full size -- perhaps due to depth of field constraints or unavoidable jaggies on the boundary between the silver and black. Overall a nice shot, though.', '2002-04-10 15:15:00.000000', NULL, 1),
(45108, 704, 955, '<td valign="top">Too bland - technically good - too vague - does not invite a second glance.</td>', 'Too bland - technically good - too vague - does not invite a second glance.', '2002-04-10 18:22:00.000000', NULL, 1),
(45109, 704, 2, '<td valign="top">Very nice macro.  Would have been nice with the same amount of the lower speaker showing as there is of the upper speaker... for symmetry''s sake.</td>', 'Very nice macro.  Would have been nice with the same amount of the lower speaker showing as there is of the upper speaker... for symmetry''s sake.', '2002-04-11 10:13:00.000000', NULL, 1),
(45110, 704, 245, '<td valign="top">this would look so much better if you had captured it at an angle that emphasized the port''s symmetry! What was playing?</td>', 'this would look so much better if you had captured it at an angle that emphasized the port''s symmetry! What was playing?', '2002-04-11 13:49:00.000000', NULL, 1),
(45111, 704, 554, '<td valign="top">The winner!</td>', 'The winner!', '2002-04-11 17:22:00.000000', NULL, 1),
(45112, 704, 933, '<td valign="top">nice composition</td>', 'nice composition', '2002-04-12 15:08:00.000000', NULL, 1),
(45113, 704, 1, '<td valign="top">Nice subject although the cropping seems poor.  I wouldn''t have cut off the right side.</td>', 'Nice subject although the cropping seems poor.  I wouldn''t have cut off the right side.', '2002-04-14 14:57:00.000000', NULL, 1),
(45114, 704, 661, '<td valign="top">Nice depth.  Interesting color and sparkle.</td>', 'Nice depth.  Interesting color and sparkle.', '2002-04-14 22:57:00.000000', NULL, 1),
(45115, 704, 509, '<td valign="top">Thanks to all for their comments and votes.  The sub was lit by a small flashlight and the shot was taken with the camera on a mini-tripod.  Reuben, I tried your suggestion before I took this shot, it came out OK, but I didn''t think people would have a clue as to what the picture was.  As for the cropping, I tried this shot a lot of times and could never get the lighting and focus just right.  This is the "cream of the crop" of my shots.  I would have also liked a smaller aperture to get the left side in focus, but my camera''s minimum is 4.0<br/>-Ben</td>', 'Thanks to all for their comments and votes.  The sub was lit by a small flashlight and the shot was taken with the camera on a mini-tripod.  Reuben, I tried your suggestion before I took this shot, it came out OK, but I didn''t think people would have a clue as to what the picture was.  As for the cropping, I tried this shot a lot of times and could never get the lighting and focus just right.  This is the "cream of the crop" of my shots.  I would have also liked a smaller aperture to get the left side in focus, but my camera''s minimum is 4.0-Ben', '2002-04-15 19:13:00.000000', NULL, 0),
(45123, 706, 255, '<td valign="top">i thought about this one!</td>', 'i thought about this one!', '2002-04-08 01:32:00.000000', NULL, 1),
(45124, 706, 107, '<td valign="top">good idea. and the colours are georgous.</td>', 'good idea. and the colours are georgous.', '2002-04-08 03:05:00.000000', NULL, 1),
(45125, 706, 142, '<td valign="top">Nice picture.  I tried doing something like this myself but I could get the lighting just right.  You captured it perfectly.</td>', 'Nice picture.  I tried doing something like this myself but I could get the lighting just right.  You captured it perfectly.', '2002-04-08 09:45:00.000000', NULL, 1),
(45126, 706, 656, '<td valign="top">Great idea. Might have been stronger with more even spacing ?</td>', 'Great idea. Might have been stronger with more even spacing ?', '2002-04-08 10:40:00.000000', NULL, 1),
(45127, 706, 718, '<td valign="top">This looks very professional.</td>', 'This looks very professional.', '2002-04-08 12:31:00.000000', NULL, 1),
(45128, 706, 813, '<td valign="top">excellent composition! good color and lighting. better than most images on PhotoDisc that suggest digital media</td>', 'excellent composition! good color and lighting. better than most images on PhotoDisc that suggest digital media', '2002-04-08 13:27:00.000000', NULL, 1),
(45129, 706, 279, '<td valign="top">So that''s what you do with all those AOL cd''s...</td>', 'So that''s what you do with all those AOL cd''s...', '2002-04-08 13:35:00.000000', NULL, 1),
(45130, 706, 156, '<td valign="top">i thought about doing something like this, dontcha love the rainbows?</td>', 'i thought about doing something like this, dontcha love the rainbows?', '2002-04-08 14:05:00.000000', NULL, 1),
(45131, 706, 772, '<td valign="top">I like both of the CD photos in this challenge... Both of them are in my top 10 favorites.  This one, however is going to score one point higher than the other one because I like the variation of color more in this photo.  You have covered a greater span of the spectrum and this is much more appealing to my eye.  Kudos!  Score: 9 :)</td>', 'I like both of the CD photos in this challenge... Both of them are in my top 10 favorites.  This one, however is going to score one point higher than the other one because I like the variation of color more in this photo.  You have covered a greater span of the spectrum and this is much more appealing to my eye.  Kudos!  Score: 9 :)', '2002-04-08 15:38:00.000000', NULL, 1),
(45132, 706, 811, '<td valign="top">sharp images</td>', 'sharp images', '2002-04-08 16:08:00.000000', NULL, 1),
(45133, 706, 714, '<td valign="top">I like your idea.  Great colors.</td>', 'I like your idea.  Great colors.', '2002-04-08 16:15:00.000000', NULL, 1),
(45134, 706, 387, '<td valign="top">cool idea, lots of interesting color and repetition. it''s the better of the ''compact disc'' shots.</td>', 'cool idea, lots of interesting color and repetition. it''s the better of the ''compact disc'' shots.', '2002-04-08 16:19:00.000000', NULL, 1),
(45135, 706, 92, '<td valign="top">WOW...nice capture and beautiful color !!!!</td>', 'WOW...nice capture and beautiful color !!!!', '2002-04-08 17:24:00.000000', NULL, 1),
(45136, 706, 441, '<td valign="top">good original shot, great capture of colours, good exposure.</td>', 'good original shot, great capture of colours, good exposure.', '2002-04-08 18:59:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(45137, 706, 327, '<td valign="top">nice, colors are great, interesting!</td>', 'nice, colors are great, interesting!', '2002-04-08 20:13:00.000000', NULL, 1),
(45138, 706, 428, '<td valign="top">I like all the colors in this shot, the idea is good, but I would have tried to get the cds to be a little more symmetrical or more random. Either way I think it would improve it.</td>', 'I like all the colors in this shot, the idea is good, but I would have tried to get the cds to be a little more symmetrical or more random. Either way I think it would improve it.', '2002-04-08 22:17:00.000000', NULL, 1),
(45139, 706, 749, '<td valign="top">This looks like a shot I''ve seen in a computer magazine recently! The colours are great, but I would prefer a bit more focus in the middle of the image.</td>', 'This looks like a shot I''ve seen in a computer magazine recently! The colours are great, but I would prefer a bit more focus in the middle of the image.', '2002-04-09 03:43:00.000000', NULL, 1),
(45140, 706, 51, '<td valign="top">good color, very sharpe, i really like both of the cd shots. the composition is nice -- somewhat off centered as far as the ordering of each cd. really good.</td>', 'good color, very sharpe, i really like both of the cd shots. the composition is nice -- somewhat off centered as far as the ordering of each cd. really good.', '2002-04-09 07:43:00.000000', NULL, 1),
