(45342, 722, 689, '<td valign="top">Had a similar idea, but went a different direction ... play ball!  Good following of the theme!</td>', 'Had a similar idea, but went a different direction ... play ball!  Good following of the theme!', '2002-04-08 02:18:00.000000', NULL, 1),
(45343, 722, 51, '<td valign="top">very cool. nice detail.</td>', 'very cool. nice detail.', '2002-04-08 10:05:00.000000', NULL, 1),
(45344, 722, 656, '<td valign="top">Bit too tight on the stiching at the bottom.  Good entry.</td>', 'Bit too tight on the stiching at the bottom.  Good entry.', '2002-04-08 10:35:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(45345, 722, 142, '<td valign="top">Great interpretation.  I love baseball.</td>', 'Great interpretation.  I love baseball.', '2002-04-08 11:26:00.000000', NULL, 1),
(45346, 722, 509, '<td valign="top">Is that a ......curve ball? = )  I think that would have been a cooler title.  Great macro shot, seems to be a little less light in the upper left corner.  Is that just the coloration of the ball?  It would have been nice if it was more even.</td>', 'Is that a ......curve ball? = )  I think that would have been a cooler title.  Great macro shot, seems to be a little less light in the upper left corner.  Is that just the coloration of the ball?  It would have been nice if it was more even.', '2002-04-08 11:28:00.000000', NULL, 1),
(45347, 722, 280, '<td valign="top">Nice composition and well focused.</td>', 'Nice composition and well focused.', '2002-04-08 14:25:00.000000', NULL, 1),
(45348, 722, 387, '<td valign="top">Nice detail and rich color!<br/></td>', 'Nice detail and rich color!', '2002-04-08 15:50:00.000000', NULL, 1),
(45349, 722, 772, '<td valign="top">Greetings!  Your photo is the last one I am judging because i weeded out all the trash and saved the best ones for last.  I don''t really know what to say about this photo, but the i like the subject, the composition, the lighting, and the concept for the ''curve''.  You get a 10.  Cheers!</td>', 'Greetings!  Your photo is the last one I am judging because i weeded out all the trash and saved the best ones for last.  I don''t really know what to say about this photo, but the i like the subject, the composition, the lighting, and the concept for the ''curve''.  You get a 10.  Cheers!', '2002-04-08 15:56:00.000000', NULL, 1),
(45350, 722, 651, '<td valign="top">Nicely done..</td>', 'Nicely done..', '2002-04-08 17:09:00.000000', NULL, 1),
(45351, 722, 811, '<td valign="top">nice detail</td>', 'nice detail', '2002-04-08 17:35:00.000000', NULL, 1),
(45352, 722, 749, '<td valign="top">The focus really brings the texture of the surface into the foreground, but the light feels a little too strong.</td>', 'The focus really brings the texture of the surface into the foreground, but the light feels a little too strong.', '2002-04-08 17:36:00.000000', NULL, 1),
(45353, 722, 92, '<td valign="top">A curve ball was one of the first thoughts for me. This is soooooo well done !</td>', 'A curve ball was one of the first thoughts for me. This is soooooo well done !', '2002-04-08 17:46:00.000000', NULL, 1),
(45354, 722, 327, '<td valign="top">nice macro...clever idea.</td>', 'nice macro...clever idea.', '2002-04-08 20:14:00.000000', NULL, 1),
(45355, 722, 57, '<td valign="top">Lots of nice curves going on, unfortunately the subject itself doesn''t excite me.  Maybe more dramatic lighting and shadows would add interest?</td>', 'Lots of nice curves going on, unfortunately the subject itself doesn''t excite me.  Maybe more dramatic lighting and shadows would add interest?', '2002-04-08 21:50:00.000000', NULL, 1),
(45356, 722, 446, '<td valign="top">Sharp image.  How much of a crop did you use?</td>', 'Sharp image.  How much of a crop did you use?', '2002-04-08 23:59:00.000000', NULL, 1),
(45357, 722, 139, '<td valign="top">I''m not a big baseball fan, but it''s a good curve nonetheless.</td>', 'I''m not a big baseball fan, but it''s a good curve nonetheless.', '2002-04-09 04:15:00.000000', NULL, 1),
(45358, 722, 156, '<td valign="top">now that''s a curve ball ;o)</td>', 'now that''s a curve ball ;o)', '2002-04-09 07:22:00.000000', NULL, 1),
(45359, 722, 352, '<td valign="top">Nice contrast and lighting, I like how the red of the stiches are really brought out.</td>', 'Nice contrast and lighting, I like how the red of the stiches are really brought out.', '2002-04-09 10:52:00.000000', NULL, 1),
(45360, 722, 472, '<td valign="top">good crisp shot</td>', 'good crisp shot', '2002-04-09 12:38:00.000000', NULL, 1),
(45361, 722, 441, '<td valign="top">Lovely detail.</td>', 'Lovely detail.', '2002-04-09 13:01:00.000000', NULL, 1),
(45362, 722, 310, '<td valign="top">good detail - wish the logo wasn''t so prominent.</td>', 'good detail - wish the logo wasn''t so prominent.', '2002-04-09 18:18:00.000000', NULL, 1),
(45363, 722, 884, '<td valign="top">Good idea, but doesn''t quite grab my interest, sorry.</td>', 'Good idea, but doesn''t quite grab my interest, sorry.', '2002-04-09 20:03:00.000000', NULL, 1),
(45364, 722, 955, '<td valign="top">technically excellent, good visual impact</td>', 'technically excellent, good visual impact', '2002-04-10 18:09:00.000000', NULL, 1),
(45365, 722, 131, '<td valign="top">creative</td>', 'creative', '2002-04-10 19:25:00.000000', NULL, 1),
(45366, 722, 714, '<td valign="top">Hmmm....baseball...my favorite sport.  Nice picture.</td>', 'Hmmm....baseball...my favorite sport.  Nice picture.', '2002-04-10 22:55:00.000000', NULL, 1),
(45367, 722, 436, '<td valign="top">clever and elegant</td>', 'clever and elegant', '2002-04-11 08:14:00.000000', NULL, 1),
(45368, 722, 245, '<td valign="top">At 3:2 you should have room to get the R in Rawlings off the edge of the photo! :)</td>', 'At 3:2 you should have room to get the R in Rawlings off the edge of the photo! :)', '2002-04-11 14:02:00.000000', NULL, 1),
(45369, 722, 661, '<td valign="top">Great Clarity.</td>', 'Great Clarity.', '2002-04-12 21:24:00.000000', NULL, 1),
(45370, 722, 671, '<td valign="top">Really nice.  Clear, good colors.  Nice framing.  I like the "Rawlings" off center.</td>', 'Really nice.  Clear, good colors.  Nice framing.  I like the "Rawlings" off center.', '2002-05-07 00:33:00.000000', NULL, 0),
(45371, 724, 596, '<td valign="top">I think this woul be better if it were a little darker.</td>', 'I think this woul be better if it were a little darker.', '2002-04-08 01:47:00.000000', NULL, 1),
(45372, 724, 107, '<td valign="top">clever title</td>', 'clever title', '2002-04-08 03:11:00.000000', NULL, 1),
(45373, 724, 772, '<td valign="top">I really like this photo but I''m wondering why you chose to go black and white with it?  This is a good macro shot and I think the natural colors would have emphasized your curvature some more.  I also know that it''s hard to find perfect bananas :)  Keep up the good work...</td>', 'I really like this photo but I''m wondering why you chose to go black and white with it?  This is a good macro shot and I think the natural colors would have emphasized your curvature some more.  I also know that it''s hard to find perfect bananas :)  Keep up the good work...', '2002-04-08 10:21:00.000000', NULL, 1),
(45374, 724, 656, '<td valign="top">Good use of B&amp;W to focus on the curves/ patterns.</td>', 'Good use of B&W to focus on the curves/ patterns.', '2002-04-08 10:37:00.000000', NULL, 1),
(45375, 724, 156, '<td valign="top">clever, i like the curves ...could use more contrast</td>', 'clever, i like the curves ...could use more contrast', '2002-04-08 13:51:00.000000', NULL, 1),
(45376, 724, 749, '<td valign="top">The curves are stark, since the famous yellow colour is lacking, but perhaps a slight yellow tint would give it a bit more warmth.</td>', 'The curves are stark, since the famous yellow colour is lacking, but perhaps a slight yellow tint would give it a bit more warmth.', '2002-04-08 16:48:00.000000', NULL, 1),
(45377, 724, 312, '<td valign="top">i like the detail here, and the black in white is a very good choice for this shot. the only thing i dislike is the dark lighting in the lower corners. it detracts from the overall composition. nice shot, nonetheless.</td>', 'i like the detail here, and the black in white is a very good choice for this shot. the only thing i dislike is the dark lighting in the lower corners. it detracts from the overall composition. nice shot, nonetheless.', '2002-04-08 17:19:00.000000', NULL, 1),
(45378, 724, 441, '<td valign="top">Woudn''t this have been great in colour?</td>', 'Woudn''t this have been great in colour?', '2002-04-08 18:24:00.000000', NULL, 1),
(45379, 724, 472, '<td valign="top">I love this picture. THe curves, shapes and tight cropping on the bananas combined with the black and white are very artistic.  a high rating.</td>', 'I love this picture. THe curves, shapes and tight cropping on the bananas combined with the black and white are very artistic.  a high rating.', '2002-04-08 20:36:00.000000', NULL, 1),
(45380, 724, 139, '<td valign="top">Har har.  Good picture.  I think smoother bananas (fewer spots) would have been better.  Did you try this in color?  Doing it in color may distract from the curves too much, or it may distract just enough from the speckles, I don''t really know. But i''d like to see it in color.</td>', 'Har har.  Good picture.  I think smoother bananas (fewer spots) would have been better.  Did you try this in color?  Doing it in color may distract from the curves too much, or it may distract just enough from the speckles, I don''t really know. But i''d like to see it in color.', '2002-04-09 04:12:00.000000', NULL, 1),
(45381, 724, 797, '<td valign="top">oh man.. i love this one. not just because i chomp bananas like a chimpanzee.  lined up with all the other entries, yours is the one that really shouts "CURVES!" even in thumbnail size.</td>', 'oh man.. i love this one. not just because i chomp bananas like a chimpanzee.  lined up with all the other entries, yours is the one that really shouts "CURVES!" even in thumbnail size.', '2002-04-09 08:37:00.000000', NULL, 1),
(45382, 724, 641, '<td valign="top">great curves and lighting, I would have liked to see the color.</td>', 'great curves and lighting, I would have liked to see the color.', '2002-04-09 08:49:00.000000', NULL, 1),
(45383, 724, 280, '<td valign="top">Needs more contrast.</td>', 'Needs more contrast.', '2002-04-09 14:11:00.000000', NULL, 1),
(45384, 724, 255, '<td valign="top">something about this really gets me, i can''t even say what! all i know is that I would proudly hang it on my kitchen wall, and for that, my friend, you get a 9!</td>', 'something about this really gets me, i can''t even say what! all i know is that I would proudly hang it on my kitchen wall, and for that, my friend, you get a 9!', '2002-04-09 18:20:00.000000', NULL, 1),
(45385, 724, 549, '<td valign="top">Beautiful. Very subtal and I like it. Nice choice, black and white when you just really want to see the yellow. Gives it more of an achitectual feel. Which is good.</td>', 'Beautiful. Very subtal and I like it. Nice choice, black and white when you just really want to see the yellow. Gives it more of an achitectual feel. Which is good.', '2002-04-09 21:41:00.000000', NULL, 1),
(45386, 724, 244, '<td valign="top">Really creative I like it.</td>', 'Really creative I like it.', '2002-04-09 21:43:00.000000', NULL, 1),
(45387, 724, 931, '<td valign="top">I like the title, but it''s hard to tell they''re bananas</td>', 'I like the title, but it''s hard to tell they''re bananas', '2002-04-10 09:31:00.000000', NULL, 1),
(45388, 724, 935, '<td valign="top">Thought this was another dirty toilet rim shot at first (not meant as a criticism). Nice picture. Think the dead-ant-like blemishes detract from the curves and shadows.</td>', 'Thought this was another dirty toilet rim shot at first (not meant as a criticism). Nice picture. Think the dead-ant-like blemishes detract from the curves and shadows.', '2002-04-10 11:01:00.000000', NULL, 1),
(45389, 724, 347, '<td valign="top">Clever title, nice abstraction, good lighting. I like it!</td>', 'Clever title, nice abstraction, good lighting. I like it!', '2002-04-10 15:01:00.000000', NULL, 1),
(45390, 724, 886, '<td valign="top">Color banana have more appeal to me.</td>', 'Color banana have more appeal to me.', '2002-04-10 16:49:00.000000', NULL, 1),
(45391, 724, 509, '<td valign="top">The bananas are too cropped, showing more of them would show the curves better.  I like that the fruit isn''t perfect (exterier marks and all).  Added with the black and white, it gives the photo more depth.</td>', 'The bananas are too cropped, showing more of them would show the curves better.  I like that the fruit isn''t perfect (exterier marks and all).  Added with the black and white, it gives the photo more depth.', '2002-04-11 08:01:00.000000', NULL, 1),
(45392, 724, 436, '<td valign="top">love it in black and white!</td>', 'love it in black and white!', '2002-04-11 09:11:00.000000', NULL, 1),
(45393, 724, 714, '<td valign="top">Not bad, but could have used some curves. :)</td>', 'Not bad, but could have used some curves. :)', '2002-04-11 10:47:00.000000', NULL, 1),
(45394, 724, 142, '<td valign="top">Nice photo.  I know this is a personal preference but I wish it were in color.  Otherwise, it is a good interpretation of the challenge.</td>', 'Nice photo.  I know this is a personal preference but I wish it were in color.  Otherwise, it is a good interpretation of the challenge.', '2002-04-11 11:38:00.000000', NULL, 1),
(45395, 724, 245, '<td valign="top">I was going to shoot one of these, but all the bananas in the store looked like crap! :) The lighting is fantastic, I love how it drops of nrear the edges.</td>', 'I was going to shoot one of these, but all the bananas in the store looked like crap! :) The lighting is fantastic, I love how it drops of nrear the edges.', '2002-04-11 13:42:00.000000', NULL, 1),
(45396, 724, 352, '<td valign="top">Good contrast, works well in black and white.</td>', 'Good contrast, works well in black and white.', '2002-04-12 15:01:00.000000', NULL, 1),
(45397, 724, 933, '<td valign="top">This one kind of grew on me.  Nice composition.  Good use of B&amp;W to emphasize the form rather than the color of the object.</td>', 'This one kind of grew on me.  Nice composition.  Good use of B&W to emphasize the form rather than the color of the object.', '2002-04-12 15:13:00.000000', NULL, 1),
(45398, 724, 1, '<td valign="top">No reason to use black and white for a shot like this.  A nice vibrant yellow perhaps with some ripened green would''ve made this a much more interesting shot.</td>', 'No reason to use black and white for a shot like this.  A nice vibrant yellow perhaps with some ripened green would''ve made this a much more interesting shot.', '2002-04-13 02:42:00.000000', NULL, 1),
(45399, 724, 671, '<td valign="top">I know black and white bring out shapes, but I would have liked it better in color.</td>', 'I know black and white bring out shapes, but I would have liked it better in color.', '2002-04-13 14:13:00.000000', NULL, 1),
(45400, 724, 739, '<td valign="top">Do you think a bit more contrast in this B&amp;W shot would have brought out the curves in the banana better?</td>', 'Do you think a bit more contrast in this B&W shot would have brought out the curves in the banana better?', '2002-04-13 15:21:00.000000', NULL, 1),
(45401, 724, 881, '<td valign="top">For some reason, my eyes keep getting distracted by the fading-to-black in corners.  Was that intentional?</td>', 'For some reason, my eyes keep getting distracted by the fading-to-black in corners.  Was that intentional?', '2002-04-13 23:15:00.000000', NULL, 1),
(45402, 724, 689, '<td valign="top">I think the choice of B&amp;W made this even better.</td>', 'I think the choice of B&W made this even better.', '2002-04-14 15:32:00.000000', NULL, 1),
(45403, 724, 387, '<td valign="top">Too all the voters wanting this in color, I shot it that way about 35 times. Trust me when I say it didn''t work well, and to me it didn''t fit the challenge in color. All it said was, "A Macro of Bananas." The black and white said, "Curves of Bananas."</td>', 'Too all the voters wanting this in color, I shot it that way about 35 times. Trust me when I say it didn''t work well, and to me it didn''t fit the challenge in color. All it said was, "A Macro of Bananas." The black and white said, "Curves of Bananas."', '2002-04-15 16:01:00.000000', NULL, 0),
(45404, 726, 270, '<td valign="top">Nice, but your camera fought you on this one. A few extra shots would have helped; one would probably not have been quite so pixelated.</td>', 'Nice, but your camera fought you on this one. A few extra shots would have helped; one would probably not have been quite so pixelated.', '2002-04-08 01:20:00.000000', NULL, 1),
(45405, 726, 820, '<td valign="top">some judicious cropping would improve this.</td>', 'some judicious cropping would improve this.', '2002-04-08 07:36:00.000000', NULL, 1),
(45406, 726, 656, '<td valign="top">cropping a bit too tight, missing the final outside curve.</td>', 'cropping a bit too tight, missing the final outside curve.', '2002-04-08 10:47:00.000000', NULL, 1),
(45407, 726, 772, '<td valign="top">Interesting perspective on a race track!  I like the curve here...</td>', 'Interesting perspective on a race track!  I like the curve here...', '2002-04-08 14:05:00.000000', NULL, 1),
(45408, 726, 142, '<td valign="top">Good representation of the subject.</td>', 'Good representation of the subject.', '2002-04-08 15:14:00.000000', NULL, 1),
(45409, 726, 92, '<td valign="top">I really like this shot ! I would have liked it a little more if it was taken lower to the ground and from inside the track a bit. Maybe that would give the straight line to the curve effect a little more and help cut out the stuff behind the top fence. BUT ! It''s a great shot !</td>', 'I really like this shot ! I would have liked it a little more if it was taken lower to the ground and from inside the track a bit. Maybe that would give the straight line to the curve effect a little more and help cut out the stuff behind the top fence. BUT ! It''s a great shot !', '2002-04-08 17:18:00.000000', NULL, 1),
(45410, 726, 57, '<td valign="top">Nice idea, perhaps crop a little bit closer to the track at the top?  Like the perspective - draws me into the photo, and around the curve of the track.</td>', 'Nice idea, perhaps crop a little bit closer to the track at the top?  Like the perspective - draws me into the photo, and around the curve of the track.', '2002-04-08 21:59:00.000000', NULL, 1),
(45411, 726, 749, '<td valign="top">Very clear curves, but it feels very flat.</td>', 'Very clear curves, but it feels very flat.', '2002-04-09 03:39:00.000000', NULL, 1),
(45412, 726, 587, '<td valign="top">''Don''t take it'' cause you cropped it off? ;)</td>', '''Don''t take it'' cause you cropped it off? ;)', '2002-04-09 06:56:00.000000', NULL, 1),
(45413, 726, 641, '<td valign="top">I like the concept and the pink lane arrows add a nice color.</td>', 'I like the concept and the pink lane arrows add a nice color.', '2002-04-09 08:07:00.000000', NULL, 1),
(45414, 726, 472, '<td valign="top">makes me want to go jogging!</td>', 'makes me want to go jogging!', '2002-04-09 12:16:00.000000', NULL, 1),
(45415, 726, 441, '<td valign="top">Good composition great curves!</td>', 'Good composition great curves!', '2002-04-09 13:57:00.000000', NULL, 1),
(45416, 726, 714, '<td valign="top">nice curves...  :)</td>', 'nice curves...  :)', '2002-04-09 16:13:00.000000', NULL, 1),
(45417, 726, 139, '<td valign="top">Very curvy.  Good idea and great angle.</td>', 'Very curvy.  Good idea and great angle.', '2002-04-09 17:04:00.000000', NULL, 1),
(45418, 726, 884, '<td valign="top">Good idea.</td>', 'Good idea.', '2002-04-09 20:13:00.000000', NULL, 1),
(45419, 726, 549, '<td valign="top">nice and curvy. Good eye on this. Nice cropping (mostly while taking the shot I''d bet) This will get high marks.<br/></td>', 'nice and curvy. Good eye on this. Nice cropping (mostly while taking the shot I''d bet) This will get high marks.', '2002-04-09 21:49:00.000000', NULL, 1),
(45420, 726, 640, '<td valign="top">Original!</td>', 'Original!', '2002-04-10 09:20:00.000000', NULL, 1),
(45421, 726, 935, '<td valign="top">Nice but not extraordinary. Junk in the upper right hand corner is distracting but not interesting.</td>', 'Nice but not extraordinary. Junk in the upper right hand corner is distracting but not interesting.', '2002-04-10 10:51:00.000000', NULL, 1),
(45422, 726, 347, '<td valign="top">There''s something funny about this one ... it looks almost pixelated, or like it was taken from a digital video camera or something.<br/>Technicalities aside, it''s an interesting shot. Perhaps being on the track and lower down might have enhanced the curves by removing the corner grasses...</td>', 'There''s something funny about this one ... it looks almost pixelated, or like it was taken from a digital video camera or something.Technicalities aside, it''s an interesting shot. Perhaps being on the track and lower down might have enhanced the curves by removing the corner grasses...', '2002-04-10 15:33:00.000000', NULL, 1),
(45423, 726, 352, '<td valign="top">This might have been better if cropped in a bit more so there were two splotches of grass instead of three.  Maybe the bottom right and teh top left.</td>', 'This might have been better if cropped in a bit more so there were two splotches of grass instead of three.  Maybe the bottom right and teh top left.', '2002-04-12 20:42:00.000000', NULL, 1),
(45424, 726, 1, '<td valign="top">Nice looking shot though the quality seems to be very grainy.  Silly title.</td>', 'Nice looking shot though the quality seems to be very grainy.  Silly title.', '2002-04-13 03:02:00.000000', NULL, 1),
(45425, 726, 2, '<td valign="top">Really nice subject, though the photo seems grainy.</td>', 'Really nice subject, though the photo seems grainy.', '2002-04-13 14:27:00.000000', NULL, 1),
(45426, 726, 739, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2002-04-13 15:24:00.000000', NULL, 1),
(45427, 726, 554, '<td valign="top">A good idea well done<br/></td>', 'A good idea well done', '2002-04-13 22:38:00.000000', NULL, 1),
(45428, 726, 113, '<td valign="top">Like the depth but the background is a little blurry.</td>', 'Like the depth but the background is a little blurry.', '2002-04-14 04:05:00.000000', NULL, 1),
(45429, 726, 955, '<td valign="top">good idea well executed would prefer curves going left to right</td>', 'good idea well executed would prefer curves going left to right', '2002-04-14 21:21:00.000000', NULL, 1),
(45430, 726, 661, '<td valign="top">Eyes are definitely drawn into this photo.  Liked the colors.</td>', 'Eyes are definitely drawn into this photo.  Liked the colors.', '2002-04-14 22:54:00.000000', NULL, 1),
(45431, 726, 428, '<td valign="top">Thanks everyone for your comments.  The title comes from the fact that in track no one likes to run in the outside lane. On some tracks the outside lane is in terrible shape, (not this one however), plus there is the perception that you have to run farther.  I framed the picture intentionally with the outside lane cut off to give that illusion of it falling off the photo.  I guess you have to be a track person to get it!<br/><br/>The pixelation that some of you were seeing is the actual color of asphalt. The grassy areas do not show that graininess, no do the white lines. <br/><br/>I had thought about cropping the top of the photo to take off the fence, but to get the correct size (640x480) it would distort the lines so I left it as is.  Plus I thought it gave a better perspective to have the upper area with the lighter area of the fence.  <br/><br/>Thanks again for all the comments!</td>', 'Thanks everyone for your comments.  The title comes from the fact that in track no one likes to run in the outside lane. On some tracks the outside lane is in terrible shape, (not this one however), plus there is the perception that you have to run farther.  I framed the picture intentionally with the outside lane cut off to give that illusion of it falling off the photo.  I guess you have to be a track person to get it!The pixelation that some of you were seeing is the actual color of asphalt. The grassy areas do not show that graininess, no do the white lines. I had thought about cropping the top of the photo to take off the fence, but to get the correct size (640x480) it would distort the lines so I left it as is.  Plus I thought it gave a better perspective to have the upper area with the lighter area of the fence.  Thanks again for all the comments!', '2002-04-15 07:43:00.000000', NULL, 0),
(45432, 727, 820, '<td valign="top">Been done.</td>', 'Been done.', '2002-04-08 08:19:00.000000', NULL, 1),
(45433, 727, 656, '<td valign="top">don''t think I get these.</td>', 'don''t think I get these.', '2002-04-08 10:42:00.000000', NULL, 1),
