(45539, 730, 301, '<td valign="top">nice shot ... is this a new violin?  Obviously no strings, but also no marks where a bridge would be</td>', 'nice shot ... is this a new violin?  Obviously no strings, but also no marks where a bridge would be', '2002-04-11 12:09:00.000000', NULL, 1),
(45540, 730, 705, '<td valign="top">nice idea; good angle, although the glare is a little bit much;</td>', 'nice idea; good angle, although the glare is a little bit much;', '2002-04-13 02:24:00.000000', NULL, 1),
(45541, 730, 1, '<td valign="top">Nice rich colors and a perfect background.  Though the glare might be a bit too distracting.</td>', 'Nice rich colors and a perfect background.  Though the glare might be a bit too distracting.', '2002-04-13 02:43:00.000000', NULL, 1),
(45542, 730, 739, '<td valign="top">The glare distracted from this picture.  Warm light would be great for this shot.</td>', 'The glare distracted from this picture.  Warm light would be great for this shot.', '2002-04-13 11:41:00.000000', NULL, 1),
(45543, 730, 637, '<td valign="top">great reflection</td>', 'great reflection', '2002-04-13 23:19:00.000000', NULL, 1),
(45544, 730, 113, '<td valign="top">I love the violin and you make it look so beautiful.  Nice.</td>', 'I love the violin and you make it look so beautiful.  Nice.', '2002-04-14 04:41:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(45545, 730, 554, '<td valign="top">I know someone who can fix that for you.  you did well!</td>', 'I know someone who can fix that for you.  you did well!', '2002-04-14 20:05:00.000000', NULL, 1),
(45546, 730, 661, '<td valign="top">Of all the instruments, I liked this one best.  Great clarity and detail.  Nice Composition.</td>', 'Of all the instruments, I liked this one best.  Great clarity and detail.  Nice Composition.', '2002-04-14 22:55:00.000000', NULL, 1),
(45547, 734, 596, '<td valign="top">Wow... i love the colors</td>', 'Wow... i love the colors', '2002-04-08 01:39:00.000000', NULL, 1),
(45548, 734, 689, '<td valign="top">Great minds think alike?</td>', 'Great minds think alike?', '2002-04-08 02:15:00.000000', NULL, 1),
(45549, 734, 656, '<td valign="top">Shame about the blown highlights.  Otherwise a really warm image with good curves.</td>', 'Shame about the blown highlights.  Otherwise a really warm image with good curves.', '2002-04-08 09:38:00.000000', NULL, 1),
(45550, 734, 772, '<td valign="top">Greetings from another guitar player!  I love the color in this photo but there is a slight focus/depth of field issue that is making me strain.  The guitar bridge and the strings are absorbing a lot of your light source in the exposure... I am assuming that this is a longer-than-standard exposure... The composition of this photo is excellent!</td>', 'Greetings from another guitar player!  I love the color in this photo but there is a slight focus/depth of field issue that is making me strain.  The guitar bridge and the strings are absorbing a lot of your light source in the exposure... I am assuming that this is a longer-than-standard exposure... The composition of this photo is excellent!', '2002-04-08 12:43:00.000000', NULL, 1),
(45551, 734, 156, '<td valign="top">i notice the glare instead of the curves</td>', 'i notice the glare instead of the curves', '2002-04-08 14:14:00.000000', NULL, 1),
(45552, 734, 749, '<td valign="top">Good foreground curve, but it could be accentuated more if the curve on the other side of the guitar was more visible.</td>', 'Good foreground curve, but it could be accentuated more if the curve on the other side of the guitar was more visible.', '2002-04-08 16:09:00.000000', NULL, 1),
(45553, 734, 651, '<td valign="top">Very nice lighting</td>', 'Very nice lighting', '2002-04-08 16:48:00.000000', NULL, 1),
(45554, 734, 92, '<td valign="top">Beautiful ....the angle is great..the light just adds life to this shot. Great shot.</td>', 'Beautiful ....the angle is great..the light just adds life to this shot. Great shot.', '2002-04-08 17:25:00.000000', NULL, 1),
(45555, 734, 509, '<td valign="top">Lot of guitar pictures here, but I think this one is the best.  It is slightly out of focus, but makes good use of the reflections to convey the curves in the body.</td>', 'Lot of guitar pictures here, but I think this one is the best.  It is slightly out of focus, but makes good use of the reflections to convey the curves in the body.', '2002-04-08 22:39:00.000000', NULL, 1),
(45556, 734, 641, '<td valign="top">Nice lighting, and the highlights make it.</td>', 'Nice lighting, and the highlights make it.', '2002-04-09 08:05:00.000000', NULL, 1),
(45557, 734, 640, '<td valign="top">I would have prefered this a lighter color</td>', 'I would have prefered this a lighter color', '2002-04-09 11:03:00.000000', NULL, 1),
(45558, 734, 734, '<td valign="top">I love the warmth that the lighting creates</td>', 'I love the warmth that the lighting creates', '2002-04-09 12:32:00.000000', NULL, 1),
(45559, 734, 472, '<td valign="top">gorgeous</td>', 'gorgeous', '2002-04-09 12:41:00.000000', NULL, 1),
(45560, 734, 884, '<td valign="top">Nice idea, very pretty.</td>', 'Nice idea, very pretty.', '2002-04-09 20:11:00.000000', NULL, 1),
(45561, 734, 714, '<td valign="top">The three lights at the bottom are real distracting and the picture looks out of focus.  I like the position of the guitar so you can see more of the curves.</td>', 'The three lights at the bottom are real distracting and the picture looks out of focus.  I like the position of the guitar so you can see more of the curves.', '2002-04-10 10:13:00.000000', NULL, 1),
(45562, 734, 301, '<td valign="top">I like the mood you''ve set with the lighting, but the bright reflections on the side of the guitar are really distracting</td>', 'I like the mood you''ve set with the lighting, but the bright reflections on the side of the guitar are really distracting', '2002-04-10 12:09:00.000000', NULL, 1),
(45563, 734, 113, '<td valign="top">Not real happy with the composition.  Perhaps further back?</td>', 'Not real happy with the composition.  Perhaps further back?', '2002-04-10 12:56:00.000000', NULL, 1),
(45564, 734, 347, '<td valign="top">To me, the straight lines of the strings, frets, and reflected light overwhelm the curvature of the guitar body.</td>', 'To me, the straight lines of the strings, frets, and reflected light overwhelm the curvature of the guitar body.', '2002-04-10 15:06:00.000000', NULL, 1),
(45565, 734, 441, '<td valign="top">lack of focus has let this shot down - unless soft image was intentional?</td>', 'lack of focus has let this shot down - unless soft image was intentional?', '2002-04-10 15:19:00.000000', NULL, 1),
(45566, 734, 886, '<td valign="top">Another guitar. Still not instersting enough.</td>', 'Another guitar. Still not instersting enough.', '2002-04-10 16:12:00.000000', NULL, 1),
(45567, 734, 139, '<td valign="top">Good idea, and nice curves.  Although it doesn''t emphasize curves quite as much as the other nearly identical theme, the image is much more appealing to me.</td>', 'Good idea, and nice curves.  Although it doesn''t emphasize curves quite as much as the other nearly identical theme, the image is much more appealing to me.', '2002-04-11 01:56:00.000000', NULL, 1),
(45568, 734, 352, '<td valign="top">Your flash left a bit of a hot spot situation on the front of the guitar</td>', 'Your flash left a bit of a hot spot situation on the front of the guitar', '2002-04-12 20:31:00.000000', NULL, 1),
(45569, 734, 1, '<td valign="top">Out of focus/and or blurred.  Try using white balance to it''s not so orange</td>', 'Out of focus/and or blurred.  Try using white balance to it''s not so orange', '2002-04-13 10:34:00.000000', NULL, 1),
(45570, 734, 446, '<td valign="top">I like this kind of shot.  I assume you wanted the highlights on the side of the instrument to add some interest.  However, the highlights are a little too strong for my tastes as they overpower the shot by drawing too much attention.  Good job nonetheless.</td>', 'I like this kind of shot.  I assume you wanted the highlights on the side of the instrument to add some interest.  However, the highlights are a little too strong for my tastes as they overpower the shot by drawing too much attention.  Good job nonetheless.', '2002-04-14 11:50:00.000000', NULL, 1),
(45571, 734, 554, '<td valign="top">is that a Martin? good lighting</td>', 'is that a Martin? good lighting', '2002-04-14 20:10:00.000000', NULL, 1),
(45572, 734, 797, '<td valign="top">Thanks people, for all your constructive comments. You are all right, of course.<br/><br/> I used two light sources. One soft lamp above the guitar, and another light bulb by the side to get the highlights.  While it was used for interest, looking back it IS quite distracting. I''m wondering how I could have made light reflect in curved way by the side of the body. <br/><br/>For those who gave me the 9''s and 10''s - I''m totally flattered by the undeserved marking. Thanks  :)</td>', 'Thanks people, for all your constructive comments. You are all right, of course. I used two light sources. One soft lamp above the guitar, and another light bulb by the side to get the highlights.  While it was used for interest, looking back it IS quite distracting. I''m wondering how I could have made light reflect in curved way by the side of the body. For those who gave me the 9''s and 10''s - I''m totally flattered by the undeserved marking. Thanks  :)', '2002-04-16 00:42:00.000000', NULL, 0),
(45573, 735, 543, '<td valign="top">Hope you two put the sign back when you were finished shooting.  bummer, eh?</td>', 'Hope you two put the sign back when you were finished shooting.  bummer, eh?', '2002-04-08 08:53:00.000000', NULL, 1),
(45574, 735, 656, '<td valign="top">would be great if we could have seen the road falling away in the background...</td>', 'would be great if we could have seen the road falling away in the background...', '2002-04-08 09:43:00.000000', NULL, 1),
(45575, 735, 772, '<td valign="top">Is that bird poop on the sign? :)  This particular photograph appears to be a little grainy in the background... Maybe try capturing some of the curvy road with the sigh on your next attempt....</td>', 'Is that bird poop on the sign? :)  This particular photograph appears to be a little grainy in the background... Maybe try capturing some of the curvy road with the sigh on your next attempt....', '2002-04-08 12:11:00.000000', NULL, 1),
(45576, 735, 714, '<td valign="top">Maybe if you focused on the sign it would catch my eye more.  I just see a sign and a bunch of unfocused bushes...   :)</td>', 'Maybe if you focused on the sign it would catch my eye more.  I just see a sign and a bunch of unfocused bushes...   :)', '2002-04-08 16:27:00.000000', NULL, 1),
(45577, 735, 749, '<td valign="top">Very clear sign, but the background feels very flat.</td>', 'Very clear sign, but the background feels very flat.', '2002-04-08 16:30:00.000000', NULL, 1),
(45578, 735, 797, '<td valign="top">nice contrast and blurred out backgrounds. maybe a little too off-center for me.</td>', 'nice contrast and blurred out backgrounds. maybe a little too off-center for me.', '2002-04-09 02:59:00.000000', NULL, 1),
(45579, 735, 139, '<td valign="top">One of the first things that came to my mind for this challenge was "curvy road signs", so you don''t get so many points for creativity.   As for execution, I would have probably framed it to put the blank space above or below the sign, to match with either the beginning or the end of the road the sign refers to.</td>', 'One of the first things that came to my mind for this challenge was "curvy road signs", so you don''t get so many points for creativity.   As for execution, I would have probably framed it to put the blank space above or below the sign, to match with either the beginning or the end of the road the sign refers to.', '2002-04-09 04:10:00.000000', NULL, 1),
(45580, 735, 472, '<td valign="top">thiswas a popular subject choice</td>', 'thiswas a popular subject choice', '2002-04-09 12:41:00.000000', NULL, 1),
(45581, 735, 280, '<td valign="top">The white mark on the arrow is distracting.</td>', 'The white mark on the arrow is distracting.', '2002-04-09 15:09:00.000000', NULL, 1),
(45582, 735, 884, '<td valign="top">The curve is there, but not too interesting..Sorry.</td>', 'The curve is there, but not too interesting..Sorry.', '2002-04-09 20:19:00.000000', NULL, 1),
(45583, 735, 935, '<td valign="top">Vacation snapshot. Uninteresting composition with a murky background.</td>', 'Vacation snapshot. Uninteresting composition with a murky background.', '2002-04-10 11:10:00.000000', NULL, 1),
(45584, 735, 352, '<td valign="top">With the sign being the subject, I think you could have framed a bit tighter around it.  There''s a bit too much background (somewhere between 1/3 and 1/2 of the shot...)</td>', 'With the sign being the subject, I think you could have framed a bit tighter around it.  There''s a bit too much background (somewhere between 1/3 and 1/2 of the shot...)', '2002-04-12 15:21:00.000000', NULL, 1),
(45585, 735, 1013, '<td valign="top">creative? not!<br/></td>', 'creative? not!', '2002-04-12 22:34:00.000000', NULL, 1),
(45586, 735, 441, '<td valign="top">focus and exposure and curves are there ok but then your pic just dies - it''s a record shot of a road sign! you''ve got to do more if you want to compete and beat the ''big boys''</td>', 'focus and exposure and curves are there ok but then your pic just dies - it''s a record shot of a road sign! you''ve got to do more if you want to compete and beat the ''big boys''', '2002-04-13 13:55:00.000000', NULL, 1),
(45587, 736, 820, '<td valign="top">So?</td>', 'So?', '2002-04-08 08:21:00.000000', NULL, 1),
(45588, 736, 656, '<td valign="top">ouch!  Really needed the focus on the knife name to make this sing.</td>', 'ouch!  Really needed the focus on the knife name to make this sing.', '2002-04-08 09:44:00.000000', NULL, 1),
(45589, 736, 772, '<td valign="top">This is a nice curve photo.  I would like it much better if the right third was in sharper focus....</td>', 'This is a nice curve photo.  I would like it much better if the right third was in sharper focus....', '2002-04-08 13:43:00.000000', NULL, 1),
(45590, 736, 811, '<td valign="top">be careful with that thing!  the thumbnail didn''t do it justice.</td>', 'be careful with that thing!  the thumbnail didn''t do it justice.', '2002-04-08 16:10:00.000000', NULL, 1),
(45591, 736, 749, '<td valign="top">The lighting on the blade edge is very clear, but the point is unclear from the reflection, which dulls that end.</td>', 'The lighting on the blade edge is very clear, but the point is unclear from the reflection, which dulls that end.', '2002-04-08 16:16:00.000000', NULL, 1),
(45592, 736, 92, '<td valign="top">I like this shot but the far right is a bit out of focus.</td>', 'I like this shot but the far right is a bit out of focus.', '2002-04-08 17:43:00.000000', NULL, 1),
(45593, 736, 587, '<td valign="top">ouch!</td>', 'ouch!', '2002-04-09 06:45:00.000000', NULL, 1),
(45594, 736, 641, '<td valign="top">Now that''s a knife..I like the lighting and the details in teh hands.</td>', 'Now that''s a knife..I like the lighting and the details in teh hands.', '2002-04-09 08:36:00.000000', NULL, 1),
(45595, 736, 472, '<td valign="top">funny title.</td>', 'funny title.', '2002-04-09 12:13:00.000000', NULL, 1),
(45596, 736, 280, '<td valign="top">May improve the image if all of the ''el hombre'' was in focus.</td>', 'May improve the image if all of the ''el hombre'' was in focus.', '2002-04-09 15:15:00.000000', NULL, 1),
(45597, 736, 549, '<td valign="top">nice idea. If it wasn''t just centered with the blade in the center, I''d of given it a higher score for creativity.</td>', 'nice idea. If it wasn''t just centered with the blade in the center, I''d of given it a higher score for creativity.', '2002-04-09 21:51:00.000000', NULL, 1),
(45598, 736, 509, '<td valign="top">Gives new meaning to look but don''t touch.  I like the concept.  Had the writing on the blade and the blade itself been more focused I would have rated this photo higher.</td>', 'Gives new meaning to look but don''t touch.  I like the concept.  Had the writing on the blade and the blade itself been more focused I would have rated this photo higher.', '2002-04-10 12:52:00.000000', NULL, 1),
(45599, 736, 715, '<td valign="top">Although I don''t like el Hombre, I do like the picture. Especially the handlines following the curves of the knive. One handline even seems to be in line with the shade on the knive. Perfect!<br/></td>', 'Although I don''t like el Hombre, I do like the picture. Especially the handlines following the curves of the knive. One handline even seems to be in line with the shade on the knive. Perfect!', '2002-04-10 13:27:00.000000', NULL, 1),
(45600, 736, 245, '<td valign="top">Please don''t hurt me! Good job on the *really* clean kinfe. I wish the entire name were in focus.</td>', 'Please don''t hurt me! Good job on the *really* clean kinfe. I wish the entire name were in focus.', '2002-04-10 13:30:00.000000', NULL, 1),
(45601, 736, 347, '<td valign="top">Hmmm. Could have been cropped a little more (the right hand side out of focus I find distracting).</td>', 'Hmmm. Could have been cropped a little more (the right hand side out of focus I find distracting).', '2002-04-10 15:19:00.000000', NULL, 1),
(45602, 736, 441, '<td valign="top">Good detail, original idea.</td>', 'Good detail, original idea.', '2002-04-10 15:27:00.000000', NULL, 1),
(45603, 736, 705, '<td valign="top">I''m thinking the focus should have been on the knife, not on the finger; the many lines created by the fingers are noisy; glad there''s no blood; the blurred thum in the foreground is distracting</td>', 'I''m thinking the focus should have been on the knife, not on the finger; the many lines created by the fingers are noisy; glad there''s no blood; the blurred thum in the foreground is distracting', '2002-04-10 21:41:00.000000', NULL, 1),
(45604, 736, 139, '<td valign="top">This is one of my favorites.</td>', 'This is one of my favorites.', '2002-04-11 02:10:00.000000', NULL, 1),
(45605, 736, 352, '<td valign="top">I like the lighting and reflection you''re getting off of the blade, especially the sharpened part, very nice.</td>', 'I like the lighting and reflection you''re getting off of the blade, especially the sharpened part, very nice.', '2002-04-12 15:11:00.000000', NULL, 1),
(45606, 738, 596, '<td valign="top">This is an awesome picture... I love it!</td>', 'This is an awesome picture... I love it!', '2002-04-08 01:45:00.000000', NULL, 1),
(45607, 738, 270, '<td valign="top">What a find! Well done.</td>', 'What a find! Well done.', '2002-04-08 02:16:00.000000', NULL, 1),
(45608, 738, 656, '<td valign="top">Cool section of road - get my car!</td>', 'Cool section of road - get my car!', '2002-04-08 07:30:00.000000', NULL, 1),
(45609, 738, 820, '<td valign="top">Seen stuff like this a billion times in stock photo books. Boring.</td>', 'Seen stuff like this a billion times in stock photo books. Boring.', '2002-04-08 08:14:00.000000', NULL, 1),
(45610, 738, 661, '<td valign="top">This is the picture I wanted to take but I didn''t want to drive up the coast to Santa Barbara.  Looks like Yosemite.  Great composition.</td>', 'This is the picture I wanted to take but I didn''t want to drive up the coast to Santa Barbara.  Looks like Yosemite.  Great composition.', '2002-04-08 08:47:00.000000', NULL, 1),
(45611, 738, 165, '<td valign="top">Nice!!</td>', 'Nice!!', '2002-04-08 09:24:00.000000', NULL, 1),
(45612, 738, 142, '<td valign="top">You can''t help but look at this entry and see curves.  Great picture.</td>', 'You can''t help but look at this entry and see curves.  Great picture.', '2002-04-08 09:41:00.000000', NULL, 1),
(45613, 738, 51, '<td valign="top">really nice!</td>', 'really nice!', '2002-04-08 10:01:00.000000', NULL, 1),
(45614, 738, 772, '<td valign="top">I like this photo...  If i''m not mistaken, this is one of my favorite motorcycle rides... Is this along the blue ridge parkway in North Carolina?  This particular perspective is really nice in the fall... About the 2nd week of October, these leaves are in full color.  This is the nicest example of road curves I have seen lately :)</td>', 'I like this photo...  If i''m not mistaken, this is one of my favorite motorcycle rides... Is this along the blue ridge parkway in North Carolina?  This particular perspective is really nice in the fall... About the 2nd week of October, these leaves are in full color.  This is the nicest example of road curves I have seen lately :)', '2002-04-08 10:42:00.000000', NULL, 1),
(45615, 738, 509, '<td valign="top">Nicely done, truly captures the topic</td>', 'Nicely done, truly captures the topic', '2002-04-08 11:40:00.000000', NULL, 1),
(45616, 738, 718, '<td valign="top">This is a great photo.  Where is this?</td>', 'This is a great photo.  Where is this?', '2002-04-08 12:27:00.000000', NULL, 1),
(45617, 738, 279, '<td valign="top">A shot like this being entered was inevitable, despite the ''predictability'' it''s a great photo, very well framed.</td>', 'A shot like this being entered was inevitable, despite the ''predictability'' it''s a great photo, very well framed.', '2002-04-08 13:36:00.000000', NULL, 1),
(45618, 738, 387, '<td valign="top">nice shot!  I gave you an 8 (would have been nine with a hitch-hiker in there somewhere).</td>', 'nice shot!  I gave you an 8 (would have been nine with a hitch-hiker in there somewhere).', '2002-04-08 15:55:00.000000', NULL, 1),
(45619, 738, 749, '<td valign="top">The road markings really help the eye follow up the image, and the wall being a different shape curve nicely offsets the road.</td>', 'The road markings really help the eye follow up the image, and the wall being a different shape curve nicely offsets the road.', '2002-04-08 16:40:00.000000', NULL, 1),
(45620, 738, 651, '<td valign="top">This is a great shot.</td>', 'This is a great shot.', '2002-04-08 16:53:00.000000', NULL, 1),
(45621, 738, 441, '<td valign="top">terrific subject for challenge, well grabbed shot</td>', 'terrific subject for challenge, well grabbed shot', '2002-04-08 17:34:00.000000', NULL, 1),
(45622, 738, 92, '<td valign="top">The ULTIMATE CURVE !!!!!! I LOVE THIS !!!!</td>', 'The ULTIMATE CURVE !!!!!! I LOVE THIS !!!!', '2002-04-08 18:16:00.000000', NULL, 1),
(45623, 738, 327, '<td valign="top">cool road, cool shot.</td>', 'cool road, cool shot.', '2002-04-08 20:12:00.000000', NULL, 1),
(45624, 738, 428, '<td valign="top">great focus and composition,</td>', 'great focus and composition,', '2002-04-08 22:08:00.000000', NULL, 1),
(45625, 738, 587, '<td valign="top">wow, I''m car sick already! ;)</td>', 'wow, I''m car sick already! ;)', '2002-04-09 07:01:00.000000', NULL, 1),
(45626, 738, 641, '<td valign="top">woa! glad I don''t have to drive on that! I like the soft feel to the colors.</td>', 'woa! glad I don''t have to drive on that! I like the soft feel to the colors.', '2002-04-09 08:28:00.000000', NULL, 1),
(45627, 738, 813, '<td valign="top">Excellent, crisp focus, sharp color, but where''s the red car?</td>', 'Excellent, crisp focus, sharp color, but where''s the red car?', '2002-04-09 10:50:00.000000', NULL, 1),
(45628, 738, 352, '<td valign="top">Very cool shot.  I like how this goes on and on...</td>', 'Very cool shot.  I like how this goes on and on...', '2002-04-09 10:59:00.000000', NULL, 1),
(45629, 738, 326, '<td valign="top">I love this shot! The only thing I would have done different is crop the bottom stones out. But still a wonderful shot!</td>', 'I love this shot! The only thing I would have done different is crop the bottom stones out. But still a wonderful shot!', '2002-04-09 10:59:00.000000', NULL, 1),
(45630, 738, 472, '<td valign="top">great shot. you found a good stretch of road!  i would have liked to see the crop cut off closer to the road at the top.</td>', 'great shot. you found a good stretch of road!  i would have liked to see the crop cut off closer to the road at the top.', '2002-04-09 12:20:00.000000', NULL, 1),
(45631, 738, 280, '<td valign="top">Fantastic location! Looks like something out of a car advert.</td>', 'Fantastic location! Looks like something out of a car advert.', '2002-04-09 15:52:00.000000', NULL, 1),
(45632, 738, 310, '<td valign="top">Perfect interpretation of the challenge theme.</td>', 'Perfect interpretation of the challenge theme.', '2002-04-09 18:11:00.000000', NULL, 1),
(45633, 738, 549, '<td valign="top">now this is a curvy road! Great shot. Good eye.</td>', 'now this is a curvy road! Great shot. Good eye.', '2002-04-09 21:45:00.000000', NULL, 1),
(45634, 738, 909, '<td valign="top">Reminds me of SR 178 up the Kern Canyon in California. Nice angle on the curve.</td>', 'Reminds me of SR 178 up the Kern Canyon in California. Nice angle on the curve.', '2002-04-09 23:17:00.000000', NULL, 1),
(45635, 738, 543, '<td valign="top">What a great road!  Cropping up 10% from the bottom would make a nicer comp, and having a drunk buddy knock over those signs would make it perfect (they''re not all that pretty, and show that the pic needs to be rotated a degree or two CCW).</td>', 'What a great road!  Cropping up 10% from the bottom would make a nicer comp, and having a drunk buddy knock over those signs would make it perfect (they''re not all that pretty, and show that the pic needs to be rotated a degree or two CCW).', '2002-04-10 11:29:00.000000', NULL, 1),
