(45648, 738, 739, '<td valign="top">Wow, what a view of this great road.  Wish I had a sports car.  Great job finding this place.</td>', 'Wow, what a view of this great road.  Wish I had a sports car.  Great job finding this place.', '2002-04-13 15:38:00.000000', NULL, 1),
(45649, 738, 446, '<td valign="top">Wide depth of field works nicely for this shot.  The sharpness works well here also.  Looks like you were at the limit of your cameras, and my monitors, resolution to resolve the lines on the road.  Have you tried printing it?  Just enough background to make the road interesting, putting it in context.  Good job.</td>', 'Wide depth of field works nicely for this shot.  The sharpness works well here also.  Looks like you were at the limit of your cameras, and my monitors, resolution to resolve the lines on the road.  Have you tried printing it?  Just enough background to make the road interesting, putting it in context.  Good job.', '2002-04-14 11:44:00.000000', NULL, 1),
(45650, 738, 734, '<td valign="top">Where is this?  I love the image it makes me dizzy.</td>', 'Where is this?  I love the image it makes me dizzy.', '2002-04-14 13:20:00.000000', NULL, 1),
(45651, 738, 689, '<td valign="top">Nice job ... looks like a section of the Blue Ridge Parkway ... if not, still a good representation of curves!</td>', 'Nice job ... looks like a section of the Blue Ridge Parkway ... if not, still a good representation of curves!', '2002-04-14 15:45:00.000000', NULL, 1),
