(45688, 743, 749, '<td valign="top">A nice curve, but perhaps if the shot had been taken from slightly lower down, the top half of the shot wouldn''t feel so vacant.</td>', 'A nice curve, but perhaps if the shot had been taken from slightly lower down, the top half of the shot wouldn''t feel so vacant.', '2002-04-08 16:04:00.000000', NULL, 1),
(45689, 743, 441, '<td valign="top">not quite sharp and way too much sky. You need to work on your ''thirds'' - this pic has 50% sky and without loads of cloud detail your pic dies. The sky area should be no larger than 1/3rd of your image height in shots like this,</td>', 'not quite sharp and way too much sky. You need to work on your ''thirds'' - this pic has 50% sky and without loads of cloud detail your pic dies. The sky area should be no larger than 1/3rd of your image height in shots like this,', '2002-04-08 17:45:00.000000', NULL, 1),
(45690, 743, 472, '<td valign="top">interesting.  would have been more blatabntly curvy looking if you had gotten higher up.  stand up in the back of a pickup truck?</td>', 'interesting.  would have been more blatabntly curvy looking if you had gotten higher up.  stand up in the back of a pickup truck?', '2002-04-08 20:54:00.000000', NULL, 1),
(45691, 743, 428, '<td valign="top">I like the concept of this photo, but I think I would have liked to have seen more of the road and less of the sky.</td>', 'I like the concept of this photo, but I think I would have liked to have seen more of the road and less of the sky.', '2002-04-08 21:38:00.000000', NULL, 1),
