(45737, 747, 772, '<td valign="top">I like the antique overtones and the excellent contrast in this photo... You are in my top 20... Score: 7</td>', 'I like the antique overtones and the excellent contrast in this photo... You are in my top 20... Score: 7', '2002-04-08 15:01:00.000000', NULL, 1),
(45738, 747, 312, '<td valign="top">this is very nice. i love the subject, here. the contrast is really nice and the angle and position of the subject is good, too. i think the only thing that bothers me a little is that it might be just a tad underexposed. the blacks are just too black and lose some of the detal of the wheel. good job, overall.</td>', 'this is very nice. i love the subject, here. the contrast is really nice and the angle and position of the subject is good, too. i think the only thing that bothers me a little is that it might be just a tad underexposed. the blacks are just too black and lose some of the detal of the wheel. good job, overall.', '2002-04-08 15:30:00.000000', NULL, 1),
(45739, 747, 749, '<td valign="top">I like the way the reflection is matted by the sheen on the hubcab, but I feel it needs a little more light one the centre of it.</td>', 'I like the way the reflection is matted by the sheen on the hubcab, but I feel it needs a little more light one the centre of it.', '2002-04-08 15:43:00.000000', NULL, 1),
(45740, 747, 387, '<td valign="top">Being from the Motor City, I''m always a sucker for autos. nice choice of a brushed hubcap to reduce reflection (if that was intentional!).</td>', 'Being from the Motor City, I''m always a sucker for autos. nice choice of a brushed hubcap to reduce reflection (if that was intentional!).', '2002-04-08 16:14:00.000000', NULL, 1),
(45741, 747, 472, '<td valign="top">this is an amazing image.  the texture, lighting and contrast, all perfect to me.</td>', 'this is an amazing image.  the texture, lighting and contrast, all perfect to me.', '2002-04-08 21:02:00.000000', NULL, 1),
(45742, 747, 57, '<td valign="top">I''m usually not fond of b&amp;w, but this is really nice.</td>', 'I''m usually not fond of b&w, but this is really nice.', '2002-04-08 21:46:00.000000', NULL, 1),
(45743, 747, 244, '<td valign="top">Nice shot</td>', 'Nice shot', '2002-04-08 22:36:00.000000', NULL, 1),
