(45935, 759, 714, '<td valign="top">I like your photo...I like the lighting...very good picture   :)</td>', 'I like your photo...I like the lighting...very good picture   :)', '2002-04-09 17:00:00.000000', NULL, 1),
(45936, 759, 310, '<td valign="top">very well done - the detail in egg-cellent.</td>', 'very well done - the detail in egg-cellent.', '2002-04-09 18:17:00.000000', NULL, 1),
