(45938, 759, 910, '<td valign="top">I like the perspective.  Very creative shot.  Nice.</td>', 'I like the perspective.  Very creative shot.  Nice.', '2002-04-10 01:25:00.000000', NULL, 1),
(45939, 759, 674, '<td valign="top">I really felt this composition fitted the Curves challenge perfectly!</td>', 'I really felt this composition fitted the Curves challenge perfectly!', '2002-04-10 01:28:00.000000', NULL, 1),
(45940, 759, 301, '<td valign="top">great focus, lighting &amp; composition</td>', 'great focus, lighting & composition', '2002-04-10 04:24:00.000000', NULL, 1),
(45941, 759, 931, '<td valign="top">really good lighting and point of view</td>', 'really good lighting and point of view', '2002-04-10 09:27:00.000000', NULL, 1),
(45942, 759, 543, '<td valign="top">8 is a much curvier number.  So''s nine.  Love the photo.  Slightly dark from here.</td>', '8 is a much curvier number.  So''s nine.  Love the photo.  Slightly dark from here.', '2002-04-10 11:01:00.000000', NULL, 1),
(45943, 759, 245, '<td valign="top">I am feeling sick to my stomach that I did not submit one of my own egg shots. This is a very nice picture.</td>', 'I am feeling sick to my stomach that I did not submit one of my own egg shots. This is a very nice picture.', '2002-04-10 13:14:00.000000', NULL, 1),
(45944, 759, 715, '<td valign="top">Great composition and very well focused.</td>', 'Great composition and very well focused.', '2002-04-10 13:32:00.000000', NULL, 1),
(45945, 759, 347, '<td valign="top">Wait ... I can see the twelfth egg just off on the left! Haha! Your title is wrong! :)</td>', 'Wait ... I can see the twelfth egg just off on the left! Haha! Your title is wrong! :)', '2002-04-10 15:38:00.000000', NULL, 1),
(45946, 759, 139, '<td valign="top">Great photo, great curves, and apt title. :)</td>', 'Great photo, great curves, and apt title. :)', '2002-04-11 02:04:00.000000', NULL, 1),
(45947, 759, 933, '<td valign="top">very neat shot!</td>', 'very neat shot!', '2002-04-12 15:09:00.000000', NULL, 1),
(45948, 759, 428, '<td valign="top">nice depcition of the theme, but to me the photo lacks something.  Here''s an idea...Instead of having just eleven eggs, have many more that fade into the background.  I like the use of black and white</td>', 'nice depcition of the theme, but to me the photo lacks something.  Here''s an idea...Instead of having just eleven eggs, have many more that fade into the background.  I like the use of black and white', '2002-04-12 17:10:00.000000', NULL, 1),
(45949, 759, 1, '<td valign="top">I see the twelth on the left side.  Cool shot though, black and white works here.</td>', 'I see the twelth on the left side.  Cool shot though, black and white works here.', '2002-04-13 02:45:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(45950, 759, 739, '<td valign="top">Good lighting.  The pattern in this picture also amplifies the "curve" message.</td>', 'Good lighting.  The pattern in this picture also amplifies the "curve" message.', '2002-04-13 15:19:00.000000', NULL, 1),
(45951, 759, 637, '<td valign="top">ohhhhhh.... eleven EGGS... got it</td>', 'ohhhhhh.... eleven EGGS... got it', '2002-04-13 23:23:00.000000', NULL, 1),
(45952, 759, 734, '<td valign="top">The focus and detail are excelent</td>', 'The focus and detail are excelent', '2002-04-14 13:19:00.000000', NULL, 1),
(45953, 759, 554, '<td valign="top">great idea.  I woulda liked more depth but you done good</td>', 'great idea.  I woulda liked more depth but you done good', '2002-04-14 16:42:00.000000', NULL, 1),
(45954, 759, 193, '<td valign="top">Very excellent!  You turned an average, normal subject into a spectacularly beautiful photo!  Strange, though - I count twelve...</td>', 'Very excellent!  You turned an average, normal subject into a spectacularly beautiful photo!  Strange, though - I count twelve...', '2002-04-14 16:53:00.000000', NULL, 1),
(45955, 759, 661, '<td valign="top">Nice detail on the front egg.  I thought this photo very creative.</td>', 'Nice detail on the front egg.  I thought this photo very creative.', '2002-04-14 22:49:00.000000', NULL, 1),
(45956, 759, 361, '<td valign="top">I like the horizon of curves and the use of black and white. Good perspective.</td>', 'I like the horizon of curves and the use of black and white. Good perspective.', '2002-04-15 00:21:00.000000', NULL, 1),
(45957, 760, 270, '<td valign="top">A sad shot.  Very appropriate, but the field of vision needs to be tweaked a bit.</td>', 'A sad shot.  Very appropriate, but the field of vision needs to be tweaked a bit.', '2002-04-08 01:38:00.000000', NULL, 1),
(45958, 760, 656, '<td valign="top">Unusual subject.  Could have cleaned the rubbish off the keys before shooting ;)  Stronger/ more interesting light would have helped a great deal.</td>', 'Unusual subject.  Could have cleaned the rubbish off the keys before shooting ;)  Stronger/ more interesting light would have helped a great deal.', '2002-04-08 10:25:00.000000', NULL, 1),
(45959, 760, 772, '<td valign="top">I like the title of the photograph.  "Requiem" is very befitting of the graveyard...</td>', 'I like the title of the photograph.  "Requiem" is very befitting of the graveyard...', '2002-04-08 13:45:00.000000', NULL, 1),
(45960, 760, 749, '<td valign="top">The harsh curve contrasts weill with the softer, yet more angular keys below.</td>', 'The harsh curve contrasts weill with the softer, yet more angular keys below.', '2002-04-08 15:56:00.000000', NULL, 1),
(45961, 760, 641, '<td valign="top">I like the framing and the sombre feel to it.</td>', 'I like the framing and the sombre feel to it.', '2002-04-09 08:38:00.000000', NULL, 1),
(45962, 760, 640, '<td valign="top">that''s what I call a curve!</td>', 'that''s what I call a curve!', '2002-04-09 10:38:00.000000', NULL, 1),
(45963, 760, 472, '<td valign="top">very evocative image. im only slightly bothered by the acorn or whatever that is.</td>', 'very evocative image. im only slightly bothered by the acorn or whatever that is.', '2002-04-09 12:36:00.000000', NULL, 1),
(45964, 760, 280, '<td valign="top">Strong curve but seems to lack real interest.</td>', 'Strong curve but seems to lack real interest.', '2002-04-09 13:57:00.000000', NULL, 1),
(45965, 760, 714, '<td valign="top">Nice picture....but I feel like I need glasses    :)</td>', 'Nice picture....but I feel like I need glasses    :)', '2002-04-09 16:40:00.000000', NULL, 1),
(45966, 760, 139, '<td valign="top">I find myself unable to articulate why, but I really like this one.</td>', 'I find myself unable to articulate why, but I really like this one.', '2002-04-09 17:14:00.000000', NULL, 1),
(45967, 760, 797, '<td valign="top">are those tombstones in the background? i can almost hear the funeral march being thumped out on this piano.  thanks!</td>', 'are those tombstones in the background? i can almost hear the funeral march being thumped out on this piano.  thanks!', '2002-04-09 23:49:00.000000', NULL, 1),
(45968, 760, 917, '<td valign="top">Too mush background out of focus. The small item of dirt on the keyboard could have been made the object of the focus to get a sense of interest.</td>', 'Too mush background out of focus. The small item of dirt on the keyboard could have been made the object of the focus to get a sense of interest.', '2002-04-10 05:11:00.000000', NULL, 1),
(45969, 760, 301, '<td valign="top">nice focus.  what is that thing sticking out of the (fake) keyboard???</td>', 'nice focus.  what is that thing sticking out of the (fake) keyboard???', '2002-04-10 12:04:00.000000', NULL, 1),
(45970, 760, 441, '<td valign="top">Interesting  shot,  needed a little more interest in this image.</td>', 'Interesting  shot,  needed a little more interest in this image.', '2002-04-10 14:42:00.000000', NULL, 1),
(45971, 760, 352, '<td valign="top">The background is missing something on focus.  It''s too in the middle, I''d try either bringing it further in or further out.</td>', 'The background is missing something on focus.  It''s too in the middle, I''d try either bringing it further in or further out.', '2002-04-12 20:22:00.000000', NULL, 1),
(45972, 760, 734, '<td valign="top">The lighting of ths image tell a story.. good gob</td>', 'The lighting of ths image tell a story.. good gob', '2002-04-14 13:26:00.000000', NULL, 1),
(45973, 760, 554, '<td valign="top">this is a very nice curve but I don''t know what it is</td>', 'this is a very nice curve but I don''t know what it is', '2002-04-14 19:48:00.000000', NULL, 1),
(45974, 760, 955, '<td valign="top">No comment</td>', 'No comment', '2002-04-14 21:36:00.000000', NULL, 1),
(45975, 763, 270, '<td valign="top">The framing is great.  It''s tilted just a TINY bit clockwise from straight, and the oranges are a little fuzzy, but I like the idea.</td>', 'The framing is great.  It''s tilted just a TINY bit clockwise from straight, and the oranges are a little fuzzy, but I like the idea.', '2002-04-08 01:31:00.000000', NULL, 1),
(45976, 763, 820, '<td valign="top">focus!!!!</td>', 'focus!!!!', '2002-04-08 07:37:00.000000', NULL, 1),
(45977, 763, 656, '<td valign="top">Cool!  good imagination and execution.  Could have been a bit sharper focused/ better sharpened in software to make this really ''bite''.   Bit too tightly cropped on the left and right.  Really good entry.</td>', 'Cool!  good imagination and execution.  Could have been a bit sharper focused/ better sharpened in software to make this really ''bite''.   Bit too tightly cropped on the left and right.  Really good entry.', '2002-04-08 09:49:00.000000', NULL, 1),
(45978, 763, 51, '<td valign="top">i dont want to like this at all but i do. i wish the shot was lined up a bit more and the oranged were not cut off at the sides.</td>', 'i dont want to like this at all but i do. i wish the shot was lined up a bit more and the oranged were not cut off at the sides.', '2002-04-08 09:55:00.000000', NULL, 1),
(45979, 763, 142, '<td valign="top">Very interesting.  The oranges are a little out of focus but it is still a great photo.</td>', 'Very interesting.  The oranges are a little out of focus but it is still a great photo.', '2002-04-08 11:30:00.000000', NULL, 1),
(45980, 763, 772, '<td valign="top">This photo appears to be slightly out of focus and a little on the BRIGHT side.  I would like this photo better if there was an extra row of tiles around the outside so that the oranges on the left and right sides weren''t so close to the edge of the frame.</td>', 'This photo appears to be slightly out of focus and a little on the BRIGHT side.  I would like this photo better if there was an extra row of tiles around the outside so that the oranges on the left and right sides weren''t so close to the edge of the frame.', '2002-04-08 11:32:00.000000', NULL, 1),
(45981, 763, 509, '<td valign="top">Very original!  let me guess - kitchen floor?</td>', 'Very original!  let me guess - kitchen floor?', '2002-04-08 11:47:00.000000', NULL, 1),
(45982, 763, 640, '<td valign="top">Cute, but blurry</td>', 'Cute, but blurry', '2002-04-08 11:57:00.000000', NULL, 1),
(45983, 763, 279, '<td valign="top">Why do I like this one? I don''t know. Better focus next time though.</td>', 'Why do I like this one? I don''t know. Better focus next time though.', '2002-04-08 13:37:00.000000', NULL, 1),
(45984, 763, 661, '<td valign="top">Clever!  I wish it was more clear.</td>', 'Clever!  I wish it was more clear.', '2002-04-08 14:06:00.000000', NULL, 1),
(45985, 763, 749, '<td valign="top">Hehe, me likes :o) The lighting is nicely uniform, which makes it stand out all the more.</td>', 'Hehe, me likes :o) The lighting is nicely uniform, which makes it stand out all the more.', '2002-04-08 15:48:00.000000', NULL, 1),
(45986, 763, 92, '<td valign="top">oh how cool ! What a great idea ! I do wish the angle was a little more straight so the lines and curve were lined up better.</td>', 'oh how cool ! What a great idea ! I do wish the angle was a little more straight so the lines and curve were lined up better.', '2002-04-08 18:18:00.000000', NULL, 1),
(45987, 763, 139, '<td valign="top">Doesn''t pass the vertical line test...</td>', 'Doesn''t pass the vertical line test...', '2002-04-08 18:22:00.000000', NULL, 1),
(45988, 763, 472, '<td valign="top">are these oranges?  i so wish they were in better focus.  very original</td>', 'are these oranges?  i so wish they were in better focus.  very original', '2002-04-08 21:03:00.000000', NULL, 1),
(45989, 763, 57, '<td valign="top">This is cute - the oranges are a little blurry.</td>', 'This is cute - the oranges are a little blurry.', '2002-04-08 21:56:00.000000', NULL, 1),
(45990, 763, 244, '<td valign="top">good idea looks cool, focus is too soft for my taste though</td>', 'good idea looks cool, focus is too soft for my taste though', '2002-04-08 22:51:00.000000', NULL, 1),
(45991, 763, 641, '<td valign="top">Great idea! Very cool, and wonderful color.</td>', 'Great idea! Very cool, and wonderful color.', '2002-04-09 08:50:00.000000', NULL, 1),
(45992, 763, 352, '<td valign="top">Nice originality and creativity.  Good shot!</td>', 'Nice originality and creativity.  Good shot!', '2002-04-09 10:48:00.000000', NULL, 1),
(45993, 763, 813, '<td valign="top">Extra points for creativity!  "when life gives you oranges ..."</td>', 'Extra points for creativity!  "when life gives you oranges ..."', '2002-04-09 10:49:00.000000', NULL, 1),
(45994, 763, 708, '<td valign="top">tastey...</td>', 'tastey...', '2002-04-09 13:18:00.000000', NULL, 1),
(45995, 763, 714, '<td valign="top">For some reason it reminds me of the 60''s and 70''s.<br/>Good idea...is it a little out of focus or just me?  :)</td>', 'For some reason it reminds me of the 60''s and 70''s.Good idea...is it a little out of focus or just me?  :)', '2002-04-09 16:08:00.000000', NULL, 1),
(45996, 763, 884, '<td valign="top">Too simple...imaginative, though.</td>', 'Too simple...imaginative, though.', '2002-04-09 20:16:00.000000', NULL, 1),
(45997, 763, 549, '<td valign="top">ok, it has promise.</td>', 'ok, it has promise.', '2002-04-09 21:57:00.000000', NULL, 1),
(45998, 763, 205, '<td valign="top">2 more fruits would have filled up the whole picture making it more interesting.</td>', '2 more fruits would have filled up the whole picture making it more interesting.', '2002-04-10 00:24:00.000000', NULL, 1),
(45999, 763, 935, '<td valign="top">Interesting idea. Don''t care for the execution. The color tones on the tiles bother me -- would be better if it were a more pure white with starker grid lines. Seems a little out of focus, particularly on the left. For this type of staged photo I''d expect better formed and matched oranges -- might have added interest to have the stem sides up too. That''s also the angle at which all of the oranges would have tended to be round. The cropping is not good -- better if you had whole tiles on the left and right, better still if you could have pulled out further and done a bigger, longer curve.</td>', 'Interesting idea. Don''t care for the execution. The color tones on the tiles bother me -- would be better if it were a more pure white with starker grid lines. Seems a little out of focus, particularly on the left. For this type of staged photo I''d expect better formed and matched oranges -- might have added interest to have the stem sides up too. That''s also the angle at which all of the oranges would have tended to be round. The cropping is not good -- better if you had whole tiles on the left and right, better still if you could have pulled out further and done a bigger, longer curve.', '2002-04-10 10:50:00.000000', NULL, 1),
(46000, 763, 543, '<td valign="top">Good idea.  Better with the tiles squared off and with a little more room on the sides.</td>', 'Good idea.  Better with the tiles squared off and with a little more room on the sides.', '2002-04-10 11:43:00.000000', NULL, 1),
(46001, 763, 948, '<td valign="top">It''s simple, but what the heck. I love the funky oranges. They make me think of detergent.</td>', 'It''s simple, but what the heck. I love the funky oranges. They make me think of detergent.', '2002-04-10 13:39:00.000000', NULL, 1),
(46002, 763, 245, '<td valign="top">Technically this isn''t a sine wave, but who cares? :) Did you try sharpening the picture at all? Since the oranges are already on the edge of the frame, I would have tried cropping them directly down the middle.</td>', 'Technically this isn''t a sine wave, but who cares? :) Did you try sharpening the picture at all? Since the oranges are already on the edge of the frame, I would have tried cropping them directly down the middle.', '2002-04-10 13:40:00.000000', NULL, 1),
(46003, 763, 347, '<td valign="top">Cute...</td>', 'Cute...', '2002-04-10 15:22:00.000000', NULL, 1),
(46004, 763, 113, '<td valign="top">I like the simple idea here, but the clarity is lacking....</td>', 'I like the simple idea here, but the clarity is lacking....', '2002-04-11 16:05:00.000000', NULL, 1),
(46005, 763, 811, '<td valign="top">Neat idea, nice contrast, but it is a little fuzzy to me.</td>', 'Neat idea, nice contrast, but it is a little fuzzy to me.', '2002-04-12 15:53:00.000000', NULL, 1),
(46006, 763, 1, '<td valign="top">Ah, I think I''ve finally figured out that these are oranges on a tiled floor.  Nice idea.  Simple yet strong.</td>', 'Ah, I think I''ve finally figured out that these are oranges on a tiled floor.  Nice idea.  Simple yet strong.', '2002-04-13 10:30:00.000000', NULL, 1),
(46007, 763, 2, '<td valign="top">Is this a photograph of a painting?  It looks fake.  And the bottom right corner is blank -- a bad rotate job?</td>', 'Is this a photograph of a painting?  It looks fake.  And the bottom right corner is blank -- a bad rotate job?', '2002-04-13 14:29:00.000000', NULL, 1),
(46008, 763, 739, '<td valign="top">My eyes are playing connect the dots. :)</td>', 'My eyes are playing connect the dots. :)', '2002-04-13 15:26:00.000000', NULL, 1),
(46009, 763, 734, '<td valign="top">Very original,.. I like it.</td>', 'Very original,.. I like it.', '2002-04-14 13:23:00.000000', NULL, 1),
(46010, 763, 441, '<td valign="top">very original suggestion of curves but why oranges - please dom''t say ''why not''</td>', 'very original suggestion of curves but why oranges - please dom''t say ''why not''', '2002-04-14 13:59:00.000000', NULL, 1),
(46011, 763, 689, '<td valign="top">An engineer with a sense of humor? A+ for creativity ... a 1/2 stop or so darker would have made the oranges stand out a bit more.</td>', 'An engineer with a sense of humor? A+ for creativity ... a 1/2 stop or so darker would have made the oranges stand out a bit more.', '2002-04-14 16:10:00.000000', NULL, 1),
(46012, 763, 955, '<td valign="top">No impact</td>', 'No impact', '2002-04-14 21:46:00.000000', NULL, 1),
(46013, 764, 772, '<td valign="top">Greetings from another guitarist!  I like your photograph.  I think a little more depth of field (higher number aperture setting) would have enhanced this photograph.  The guitar neck and close strings are a little out of focus.  I started with a guitar photograph myself and elected not to use it because the strings, neck, and fret straight lines distracted from the curves on the guitar....</td>', 'Greetings from another guitarist!  I like your photograph.  I think a little more depth of field (higher number aperture setting) would have enhanced this photograph.  The guitar neck and close strings are a little out of focus.  I started with a guitar photograph myself and elected not to use it because the strings, neck, and fret straight lines distracted from the curves on the guitar....', '2002-04-08 13:18:00.000000', NULL, 1),
(46014, 764, 280, '<td valign="top">The strings on the guitar seem to grab my attention and not the curve.</td>', 'The strings on the guitar seem to grab my attention and not the curve.', '2002-04-08 13:44:00.000000', NULL, 1),
(46015, 764, 428, '<td valign="top">nice perspective, I like the lighting</td>', 'nice perspective, I like the lighting', '2002-04-08 22:20:00.000000', NULL, 1),
(46016, 764, 139, '<td valign="top">That''s a great curve at the top, and maybe it deserves more attention! :)  Good work.</td>', 'That''s a great curve at the top, and maybe it deserves more attention! :)  Good work.', '2002-04-09 04:16:00.000000', NULL, 1),
(46017, 764, 641, '<td valign="top">I like the lighting very dramatic.</td>', 'I like the lighting very dramatic.', '2002-04-09 08:02:00.000000', NULL, 1),
(46018, 764, 797, '<td valign="top">from one guitar man to another.. ROCK ON.</td>', 'from one guitar man to another.. ROCK ON.', '2002-04-09 08:38:00.000000', NULL, 1),
(46019, 764, 312, '<td valign="top">this is a decent shot. i think it''s only shortcoming is that it seems a bit out of focus in spots. i also think more of the neck and bottom side of the guitar would have completed this a bit better.</td>', 'this is a decent shot. i think it''s only shortcoming is that it seems a bit out of focus in spots. i also think more of the neck and bottom side of the guitar would have completed this a bit better.', '2002-04-09 09:30:00.000000', NULL, 1),
(46020, 764, 870, '<td valign="top">For all the guitar photos... the straight lines of the strings always seem to dominate the photos.</td>', 'For all the guitar photos... the straight lines of the strings always seem to dominate the photos.', '2002-04-09 11:16:00.000000', NULL, 1),
(46021, 764, 472, '<td valign="top">i have always liked this perpective of a guitar.</td>', 'i have always liked this perpective of a guitar.', '2002-04-09 12:11:00.000000', NULL, 1),
(46022, 764, 811, '<td valign="top">has a romantic feel to it . . .</td>', 'has a romantic feel to it . . .', '2002-04-09 22:53:00.000000', NULL, 1),
(46023, 764, 714, '<td valign="top">I like the way you shot this at an angle and the lighting is great.  :)</td>', 'I like the way you shot this at an angle and the lighting is great.  :)', '2002-04-10 10:10:00.000000', NULL, 1),
(46024, 764, 245, '<td valign="top">pull that focus forward! I would have placed the guitar a bit closer to the right side, to emphasize the front of it.</td>', 'pull that focus forward! I would have placed the guitar a bit closer to the right side, to emphasize the front of it.', '2002-04-11 14:07:00.000000', NULL, 1),
(46025, 764, 1, '<td valign="top">The small DOF doesn''t work well for this shot.. Try a higher aperture.</td>', 'The small DOF doesn''t work well for this shot.. Try a higher aperture.', '2002-04-11 16:44:00.000000', NULL, 1),
(46026, 764, 352, '<td valign="top">Nice angle, good lighting.  I like the 2d effect that you''ve achieved here.</td>', 'Nice angle, good lighting.  I like the 2d effect that you''ve achieved here.', '2002-04-12 20:16:00.000000', NULL, 1),
(46027, 764, 656, '<td valign="top">okay colour and angle makes this more interesting than if it was straight up and down.  <br/>Suffered due to several other guitar shots that are technically better executed.</td>', 'okay colour and angle makes this more interesting than if it was straight up and down.  Suffered due to several other guitar shots that are technically better executed.', '2002-04-13 00:53:00.000000', NULL, 1),
(46028, 764, 739, '<td valign="top">Love the warm lighting!! Excellent shot.</td>', 'Love the warm lighting!! Excellent shot.', '2002-04-13 11:28:00.000000', NULL, 1),
(46029, 764, 637, '<td valign="top">Well done, but &amp;lt;yawn&amp;gt;</td>', 'Well done, but &lt;yawn&gt;', '2002-04-13 23:41:00.000000', NULL, 1),
(46030, 764, 554, '<td valign="top">nicely lit   good framing too</td>', 'nicely lit   good framing too', '2002-04-14 19:53:00.000000', NULL, 1),
(46031, 764, 955, '<td valign="top">No comment</td>', 'No comment', '2002-04-14 21:34:00.000000', NULL, 1),
(46032, 765, 820, '<td valign="top">Yes, they are colorful vases. Not enough to hold my interest though, and not enough curviness, strictly speaking.</td>', 'Yes, they are colorful vases. Not enough to hold my interest though, and not enough curviness, strictly speaking.', '2002-04-08 08:04:00.000000', NULL, 1),
