(46150, 772, 459, '<td valign="top">Beautiful photo!    Curves?</td>', 'Beautiful photo!    Curves?', '2002-04-08 13:56:00.000000', NULL, 1),
(46151, 772, 661, '<td valign="top">Gotta  love Yosemite!!</td>', 'Gotta  love Yosemite!!', '2002-04-08 14:13:00.000000', NULL, 1),
(46152, 772, 156, '<td valign="top">absolutely breathtaking</td>', 'absolutely breathtaking', '2002-04-08 14:18:00.000000', NULL, 1),
(46153, 772, 387, '<td valign="top">hey, it''s a painting, wait. It''s a photo, hmmm. Nice shot, good use of framing. only thing to make it a touch better would have been moving the waterfall to a high interest point (rule of thirds) and get more of the pine tree from the left. you''re lucky to have scenes like that near you.</td>', 'hey, it''s a painting, wait. It''s a photo, hmmm. Nice shot, good use of framing. only thing to make it a touch better would have been moving the waterfall to a high interest point (rule of thirds) and get more of the pine tree from the left. you''re lucky to have scenes like that near you.', '2002-04-08 16:18:00.000000', NULL, 1),
(46154, 772, 279, '<td valign="top">Beautiful, but banal.</td>', 'Beautiful, but banal.', '2002-04-08 17:11:00.000000', NULL, 1),
(46155, 772, 749, '<td valign="top">Difficult, the foreground trees are very dark, yet the main scenery feels washed out. However, you''ve managed to get a huge amount of detail into the shot.</td>', 'Difficult, the foreground trees are very dark, yet the main scenery feels washed out. However, you''ve managed to get a huge amount of detail into the shot.', '2002-04-08 17:38:00.000000', NULL, 1),
